#[cfg(target_os = "macos")]
const _: [(); 100] = [(); std::mem::offset_of!(ProcBsdInfo, pgid)];
#[cfg(target_os = "macos")]
const _: [(); 120] = [(); std::mem::offset_of!(ProcBsdInfo, start_tvsec)];
#[cfg(target_os = "macos")]
const _: [(); 64] = [(); std::mem::size_of::<ProcBsdShortInfo>()];
#[cfg(target_os = "macos")]
const _: [(); 0] = [(); std::mem::offset_of!(ProcBsdShortInfo, pid)];
#[cfg(target_os = "macos")]
const _: [(); 8] = [(); std::mem::offset_of!(ProcBsdShortInfo, pgid)];
#[cfg(target_os = "macos")]
