    fn temp_root(name: &str) -> std::path::PathBuf {
        crate::util::test_scratch_dir(&format!("wake-{name}"))
    }

    const B246_ROUND: &str = "r246";
    const B246_TASK: &str = "B246";
    const B246_ATTEMPT: &str = "B246-A0001";
    const B246_AGENT: &str = "executor-opencode";
    const B246_ROLE: &str = "primary";
    const B246_HEAD: &str = "2462462462462462462462462462462462462462";
    const B246_SOURCE_WAKE: &str = "019fc246-1111-4222-8333-444455556666";
    const B246_SUCCESSOR_WAKE: &str = "019fc246-7777-4888-8999-aaaabbbbcccc";
    const B246_SOURCE_DIGEST: &str =
        "1111111111111111111111111111111111111111111111111111111111111111";
    const B246_SUCCESSOR_DIGEST: &str =
        "2222222222222222222222222222222222222222222222222222222222222222";
    const B246_RENDERED_DIGEST: &str =
        "3333333333333333333333333333333333333333333333333333333333333333";
    const B246_EVIDENCE_DIGEST: &str =
        "4444444444444444444444444444444444444444444444444444444444444444";
    const B246_WINDOW_DIGEST: &str =
        "5555555555555555555555555555555555555555555555555555555555555555";

    fn b246_continuation(attempt: &str, agent: &str) -> String {
        format!("review:{B246_ROUND}:{B246_TASK}:{attempt}:{B246_ROLE}:{agent}")
    }

    fn b246_wake_event(
        wake_id: &str,
        attempt: &str,
        agent: &str,
        request_digest: &str,
        superseded_wake_id: Option<&str>,
        provider: &str,
    ) -> orch_core::EventRecord {
        let continuation_id = b246_continuation(attempt, agent);
        let mut payload = serde_json::json!({
            "wakeId": wake_id,
            "continuationId": continuation_id,
            "attemptId": attempt,
            "agent": agent,
            "providerKind": provider,
            "requestMessageSha256": request_digest,
            "renderedMessageSha256": B246_RENDERED_DIGEST,
            "requestSessionId": null,
            "backendState": "pending",
            "probeOffset": 0,
            "logPath": format!("/tmp/{wake_id}.jsonl"),
        });
        if let Some(source) = superseded_wake_id {
            payload["supersededWakeId"] = serde_json::json!(source);
        }
        ledger::event(
            "WakeIssued",
            "runtime:orch",
            Some(B246_TASK),
            Some(B246_ROUND),
            payload,
        )
    }

    fn b246_review_event(
        wake_id: &str,
        attempt: &str,
        agent: &str,
        request_digest: &str,
    ) -> orch_core::EventRecord {
        ledger::event(
            "ReviewRequested",
            "runtime:orch",
            Some(B246_TASK),
            Some(B246_ROUND),
            serde_json::json!({
                "attemptId": attempt,
                "role": B246_ROLE,
                "agent": agent,
                "deadlineSecs": 900,
                "wakeId": wake_id,
                "continuationId": b246_continuation(attempt, agent),
                "requestMessageSha256": request_digest,
                "renderedMessageSha256": B246_RENDERED_DIGEST,
                "providerKind": "opencode",
                "requestSessionId": null,
                "logPath": format!("/tmp/{wake_id}.jsonl"),
                "reviewedHead": B246_HEAD,
            }),
        )
    }

    fn b246_receipt_event(
        wake_id: &str,
        attempt: &str,
        agent: &str,
        request_digest: &str,
        session: &str,
    ) -> orch_core::EventRecord {
        let receipt = BackendReceipt {
            kind: BackendReceiptKind::OpenCode,
            wake_id: wake_id.to_string(),
            continuation_id: b246_continuation(attempt, agent),
            message_sha256: request_digest.to_string(),
            request_session_id: None,
            observed_session_id: Some(session.to_string()),
            probe_offset: 0,
            probe_end: 246,
            signed_pin: None,
        };
        backend_receipt_event(
            B246_ROUND,
            Some(B246_TASK),
            Some(attempt),
            agent,
            B246_RENDERED_DIGEST,
            &format!("/tmp/{wake_id}.jsonl"),
            &receipt,
            B246_WINDOW_DIGEST,
        )
    }

    fn b246_source_receipt() -> orch_core::EventRecord {
        b246_receipt_event(
            B246_SOURCE_WAKE,
            B246_ATTEMPT,
            B246_AGENT,
            B246_SOURCE_DIGEST,
            "ses_b246_source",
        )
    }

    fn b246_death_event_for(wake_id: &str, attempt: &str, agent: &str) -> orch_core::EventRecord {
        let action_id =
            sha256_hex(format!("managed-session-death\0{B246_ROUND}\0{wake_id}").as_bytes());
        ledger::event(
            "ManagedWakeAttachState",
            "runtime:orch",
            Some(B246_TASK),
            Some(B246_ROUND),
            serde_json::json!({
                "actionId": action_id,
                "phase": "session-death-declared",
                "wakeId": wake_id,
                "attemptId": attempt,
                "role": B246_ROLE,
                "agent": agent,
                "evidenceSha256": B246_EVIDENCE_DIGEST,
                "outcome": "DeliveredTerminal",
            }),
        )
    }

    fn b246_death_event() -> orch_core::EventRecord {
        b246_death_event_for(B246_SOURCE_WAKE, B246_ATTEMPT, B246_AGENT)
    }

    fn b261_death_event(wake_id: &str, outcome: &str, phase: &str) -> orch_core::EventRecord {
        ledger::event(
            "ManagedWakeAttachState",
            "runtime:orch",
            Some(B246_TASK),
            Some(B246_ROUND),
            serde_json::json!({
                "actionId": format!("b261-{wake_id}"),
                "phase": phase,
                "wakeId": wake_id,
                "attemptId": B246_ATTEMPT,
                "role": B246_ROLE,
                "agent": B246_AGENT,
                "evidenceSha256": B246_EVIDENCE_DIGEST,
                "outcome": outcome,
            }),
        )
    }

    fn b246_valid_supersession_events() -> Vec<orch_core::EventRecord> {
        vec![
            b246_wake_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
                None,
                "opencode",
            ),
            b246_review_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
            ),
            b246_source_receipt(),
            b246_death_event(),
            b246_wake_event(
                B246_SUCCESSOR_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SUCCESSOR_DIGEST,
                Some(B246_SOURCE_WAKE),
                "opencode",
            ),
            b246_review_event(
                B246_SUCCESSOR_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SUCCESSOR_DIGEST,
            ),
        ]
    }

    fn b264_receiptless_supersession_events(outcome: &str) -> Vec<orch_core::EventRecord> {
        let mut events = b246_valid_supersession_events();
        events.remove(2);
        events[2].payload.as_mut().unwrap()["outcome"] = serde_json::json!(outcome);
        events
    }

    #[test]
    fn b264_receiptless_ordinary_successor_projects_but_explicit_reissue_stays_strict() {
        for outcome in [
            "TruncatedNoTerminal",
            "StoppedByHardDeadline",
            "StoppedByAuthenticatedCancel",
        ] {
            let events = b264_receiptless_supersession_events(outcome);
            let projection = wake_supersession_projection(&events, B246_ROUND).unwrap();
            assert_eq!(
                projection.successor_by_source.get(B246_SOURCE_WAKE),
                Some(&B246_SUCCESSOR_WAKE.to_string()),
                "outcome={outcome}"
            );
            let active = active_wakes_from_events(&events, B246_ROUND, B246_AGENT).unwrap();
            assert_eq!(active.len(), 1, "outcome={outcome}");
            assert_eq!(active[0].wake_id, B246_SUCCESSOR_WAKE);

            let successor = durable_receipt_facts(&events[3]).unwrap();
            let state = receipt_ledger_state(&events, &successor).unwrap();
            assert_eq!(state.review_requested_count, 1);
            assert_eq!(state.receipt_count, 0);

            let error = reissue_authorization_from_events(
                Path::new("/unused-before-receipt-check"),
                &events,
                B246_ROUND,
                B246_SOURCE_WAKE,
            )
            .unwrap_err();
            assert!(
                format!("{error:#}").contains("exactly one authenticated accepted backend receipt"),
                "outcome={outcome} error={error:#}"
            );
        }

        let delivered = b264_receiptless_supersession_events("DeliveredTerminal");
        let error = wake_supersession_projection(&delivered, B246_ROUND).unwrap_err();
        assert!(format!("{error:#}").contains("release-eligible"));
    }

    #[test]
    fn b264_receiptless_source_rejects_degraded_malformed_and_duplicate_receipts() {
        let base = b264_receiptless_supersession_events("TruncatedNoTerminal");
        let source = durable_receipt_facts(&base[0]).unwrap();

        let mut degraded = base.clone();
        degraded.insert(
            2,
            degraded_backend_receipt_event(B246_ROUND, &source, "uncertain source acceptance"),
        );
        let error = wake_supersession_projection(&degraded, B246_ROUND).unwrap_err();
        assert!(format!("{error:#}").contains("degraded backend receipt"));

        let mut malformed = base.clone();
        let mut malformed_receipt = b246_source_receipt();
        malformed_receipt.payload.as_mut().unwrap()["agent"] =
            serde_json::json!("executor-opencode-other");
        malformed.insert(2, malformed_receipt);
        let error = wake_supersession_projection(&malformed, B246_ROUND).unwrap_err();
        assert!(format!("{error:#}").contains("conflicting backend receipt"));

        let mut duplicate = b246_valid_supersession_events();
        duplicate.insert(3, b246_source_receipt());
        let error = wake_supersession_projection(&duplicate, B246_ROUND).unwrap_err();
        assert!(format!("{error:#}").contains("duplicate accepted backend receipts"));
    }

    #[test]
    fn b264_late_accepted_receipt_preserves_degraded_history_and_fences_respawn() {
        let mut events = b264_receiptless_supersession_events("TruncatedNoTerminal");
        let successor = durable_receipt_facts(&events[3]).unwrap();
        events.push(degraded_backend_receipt_event(
            B246_ROUND,
            &successor,
            "post-spawn canonical reconcile failed",
        ));
        events.push(ledger::event(
            "ActionRejected",
            "runtime:orch",
            Some(B246_TASK),
            Some(B246_ROUND),
            serde_json::json!({
                "actionId": B246_SUCCESSOR_WAKE,
                "operation": "wake-backend-receipt",
                "exitCode": 3,
                "reason": "degraded after spawn",
            }),
        ));
        events.push(b246_receipt_event(
            B246_SUCCESSOR_WAKE,
            B246_ATTEMPT,
            B246_AGENT,
            B246_SUCCESSOR_DIGEST,
            "ses_b264_late_successor",
        ));

        let state = receipt_ledger_state(&events, &successor).unwrap();
        assert_eq!(state.receipt_count, 1);
        assert!(state.receipt_action_rejected);
        let active = active_wakes_from_events(&events, B246_ROUND, B246_AGENT).unwrap();
        assert_eq!(active.len(), 1);
        assert_eq!(active[0].wake_id, B246_SUCCESSOR_WAKE);
        assert!(active[0].backend_accepted);
        assert!(matches!(
            wake_fence_decision(
                &active,
                B246_AGENT,
                &WakeIntent::Continuation(b246_continuation(B246_ATTEMPT, B246_AGENT)),
                B246_SUCCESSOR_DIGEST,
                1,
            )
            .unwrap(),
            WakeFenceOutcome::Idempotent { .. }
        ));

        let mut accepted_source_with_degraded_history = b246_valid_supersession_events();
        let accepted_source =
            durable_receipt_facts(&accepted_source_with_degraded_history[0]).unwrap();
        accepted_source_with_degraded_history.insert(
            2,
            degraded_backend_receipt_event(
                B246_ROUND,
                &accepted_source,
                "accepted later by exact reconcile",
            ),
        );
        wake_supersession_projection(&accepted_source_with_degraded_history, B246_ROUND)
            .expect("an exact accepted receipt remains authoritative after degraded diagnostics");
    }

    #[test]
    fn b262_receipt_guard_targets_latest_request_and_still_rejects_collision() {
        let later_wake = "019fc262-7777-4888-8999-aaaabbbbcccc";
        let later_digest = "7777777777777777777777777777777777777777777777777777777777777777";
        let events = vec![
            b246_wake_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
                None,
                "opencode",
            ),
            b246_review_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
            ),
            b246_wake_event(
                later_wake,
                B246_ATTEMPT,
                B246_AGENT,
                later_digest,
                None,
                "opencode",
            ),
            b246_review_event(later_wake, B246_ATTEMPT, B246_AGENT, later_digest),
        ];
        let current = current_review_request(&events, B246_ROUND, B246_TASK, B246_ROLE)
            .expect("the later request is current");
        assert_eq!(payload_string(current, "wakeId"), Some(later_wake));

        let later = durable_receipt_facts(&events[2]).unwrap();
        let state = receipt_ledger_state(&events, &later).unwrap();
        assert_eq!(state.review_requested_count, 1);
        assert_eq!(state.receipt_count, 0);

        let mut old_receipted = events.clone();
        old_receipted.push(b246_source_receipt());
        let source = durable_receipt_facts(&old_receipted[0]).unwrap();
        let old_state = receipt_ledger_state(&old_receipted, &source).unwrap();
        assert_eq!(old_state.review_requested_count, 1);
        assert_eq!(old_state.receipt_count, 1);

        let mut drifted = events;
        drifted[3].payload.as_mut().unwrap()["agent"] =
            serde_json::json!("executor-opencode-other");
        let error = receipt_ledger_state(&drifted, &later)
            .expect_err("the current request's identity drift must still hit the guard");
        assert!(error.to_string().contains("conflicting ReviewRequested"));
    }

    #[test]
    fn b262_degraded_receipt_is_append_once_and_keeps_the_spawn_fenced() {
        let root = temp_root("b262-degraded-receipt");
        fs::create_dir_all(root.join(format!("coordination/rounds/{B246_ROUND}"))).unwrap();
        let wake = b246_wake_event(
            B246_SOURCE_WAKE,
            B246_ATTEMPT,
            B246_AGENT,
            B246_SOURCE_DIGEST,
            None,
            "opencode",
        );
        let request = b246_review_event(
            B246_SOURCE_WAKE,
            B246_ATTEMPT,
            B246_AGENT,
            B246_SOURCE_DIGEST,
        );
        ledger::append(&root, B246_ROUND, &[wake, request]).unwrap();

        for reason in [
            "current request collision",
            "later diagnostic must not duplicate",
        ] {
            let error =
                reject_degraded_backend_receipt::<()>(&root, B246_ROUND, B246_SOURCE_WAKE, reason)
                    .unwrap_err();
            assert!(failure::is_action_rejection(&error));
        }

        let events = read_round_ledger_events(&root, B246_ROUND).unwrap();
        assert_eq!(
            events
                .iter()
                .filter(|event| {
                    payload_string(event, "agentEvent") == Some(DEGRADED_BACKEND_RECEIPT_EVENT)
                })
                .count(),
            1
        );
        assert_eq!(
            events
                .iter()
                .filter(|event| {
                    event.kind == "ActionRejected"
                        && payload_string(event, "actionId") == Some(B246_SOURCE_WAKE)
                })
                .count(),
            1
        );
        let active = active_wakes_from_events(&events, B246_ROUND, B246_AGENT).unwrap();
        assert_eq!(active.len(), 1);
        assert!(!active[0].backend_accepted);
        assert!(!active[0].wrapper_exited);
        assert!(matches!(
            wake_fence_decision(
                &active,
                B246_AGENT,
                &WakeIntent::Continuation(b246_continuation(B246_ATTEMPT, B246_AGENT)),
                B246_SOURCE_DIGEST,
                1,
            )
            .unwrap(),
            WakeFenceOutcome::Idempotent { .. }
        ));
        fs::remove_dir_all(root).unwrap();
    }

