    #[test]
    fn b261_only_authenticated_terminal_deaths_release_the_exact_wake() {
        let base = vec![
            b246_wake_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
                None,
                "opencode",
            ),
            b246_review_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
            ),
        ];
        for outcome in [
            "TruncatedNoTerminal",
            "StoppedByHardDeadline",
            "StoppedByAuthenticatedCancel",
        ] {
            let mut events = base.clone();
            events.push(b261_death_event(
                B246_SOURCE_WAKE,
                outcome,
                "session-death-declared",
            ));
            assert!(
                active_wakes_from_events(&events, B246_ROUND, B246_AGENT)
                    .unwrap()
                    .is_empty(),
                "authenticated terminal death must release outcome={outcome}"
            );
            assert_eq!(
                active_wakes_from_events_raw(&events, B246_ROUND, B246_AGENT)
                    .unwrap()
                    .len(),
                1,
                "explicit reissue still needs the unfiltered source"
            );
        }

        for (outcome, phase) in [
            ("DeliveredTerminal", "session-death-declared"),
            ("OperationalError", "session-death-declared"),
            ("StoppedByHardDeadline", "source-terminal"),
        ] {
            let mut events = base.clone();
            events.push(b261_death_event(B246_SOURCE_WAKE, outcome, phase));
            assert_eq!(
                active_wakes_from_events(&events, B246_ROUND, B246_AGENT)
                    .unwrap()
                    .len(),
                1,
                "unproven/non-death state must not release outcome={outcome} phase={phase}"
            );
        }
    }

    #[test]
    fn b261_declared_death_is_wake_scoped_and_newer_wake_rearms_the_slot() {
        let second = "019fc261-7777-4888-8999-aaaabbbbcccc";
        let mut death_of_first_only = vec![
            b246_wake_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
                None,
                "opencode",
            ),
            b246_review_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
            ),
            b246_wake_event(
                second,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
                None,
                "opencode",
            ),
            b261_death_event(
                B246_SOURCE_WAKE,
                "StoppedByHardDeadline",
                "session-death-declared",
            ),
        ];
        let active =
            active_wakes_from_events(&death_of_first_only, B246_ROUND, B246_AGENT).unwrap();
        assert_eq!(active.len(), 1);
        assert_eq!(
            active[0].wake_id, second,
            "death must not leak to a peer wakeId"
        );

        death_of_first_only.swap(2, 3);
        let active =
            active_wakes_from_events(&death_of_first_only, B246_ROUND, B246_AGENT).unwrap();
        assert_eq!(active.len(), 1);
        assert_eq!(
            active[0].wake_id, second,
            "a WakeIssued after the death declaration must re-arm the slot"
        );
    }

    #[test]
    fn b261_death_identity_mismatch_never_releases_and_ambiguity_still_fails_closed() {
        let base = vec![
            b246_wake_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
                None,
                "opencode",
            ),
            b246_review_event(
                B246_SOURCE_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SOURCE_DIGEST,
            ),
        ];
        for field in ["round", "task", "attempt", "role", "agent", "wake"] {
            let mut death = b261_death_event(
                B246_SOURCE_WAKE,
                "TruncatedNoTerminal",
                "session-death-declared",
            );
            match field {
                "round" => death.round = Some("r-other".to_string()),
                "task" => death.task_id = Some("B999".to_string()),
                "attempt" => {
                    death.payload.as_mut().unwrap()["attemptId"] = serde_json::json!("B246-A0002")
                }
                "role" => death.payload.as_mut().unwrap()["role"] = serde_json::json!("secondary"),
                "agent" => {
                    death.payload.as_mut().unwrap()["agent"] = serde_json::json!("executor-other")
                }
                "wake" => {
                    death.payload.as_mut().unwrap()["wakeId"] =
                        serde_json::json!(B246_SUCCESSOR_WAKE)
                }
                _ => unreachable!(),
            }
            let mut events = base.clone();
            events.push(death);
            assert_eq!(
                active_wakes_from_events(&events, B246_ROUND, B246_AGENT)
                    .unwrap()
                    .len(),
                1,
                "mismatched {field} must fail closed"
            );
        }

        let second = "019fc261-aaaa-4bbb-8ccc-ddddeeeeffff";
        let mut ambiguous = base;
        ambiguous.push(b246_wake_event(
            second,
            B246_ATTEMPT,
            B246_AGENT,
            B246_SOURCE_DIGEST,
            None,
            "opencode",
        ));
        let active = active_wakes_from_events(&ambiguous, B246_ROUND, B246_AGENT).unwrap();
        assert_eq!(active.len(), 2);
        let error = wake_fence_decision(
            &active,
            B246_AGENT,
            &WakeIntent::Continuation(b246_continuation(B246_ATTEMPT, B246_AGENT)),
            B246_SOURCE_DIGEST,
            2,
        )
        .unwrap_err();
        let ambiguity_diagnostic = ["has ambiguous multiple", "live wakes"].join(" ");
        assert!(error.contains(&ambiguity_diagnostic), "{error}");
    }

