    #[test]
    fn b246_receipt_reconcile_accepts_only_members_of_a_validated_multi_hop_chain() {
        let third_wake = "019fc246-dddd-4eee-8fff-000011112222";
        let third_digest = "6666666666666666666666666666666666666666666666666666666666666666";
        let mut events = b246_valid_supersession_events();
        events.extend([
            b246_receipt_event(
                B246_SUCCESSOR_WAKE,
                B246_ATTEMPT,
                B246_AGENT,
                B246_SUCCESSOR_DIGEST,
                "ses_b246_successor",
            ),
            b246_death_event_for(B246_SUCCESSOR_WAKE, B246_ATTEMPT, B246_AGENT),
            b246_wake_event(
                third_wake,
                B246_ATTEMPT,
                B246_AGENT,
                third_digest,
                Some(B246_SUCCESSOR_WAKE),
                "opencode",
            ),
            b246_review_event(third_wake, B246_ATTEMPT, B246_AGENT, third_digest),
        ]);
        let projection = wake_supersession_projection(&events, B246_ROUND).unwrap();
        assert_eq!(
            projection.successor_by_source.get(B246_SOURCE_WAKE),
            Some(&B246_SUCCESSOR_WAKE.to_string())
        );
        assert_eq!(
            projection.successor_by_source.get(B246_SUCCESSOR_WAKE),
            Some(&third_wake.to_string())
        );
        assert_eq!(
            supersession_leaf(&projection, B246_SOURCE_WAKE),
            Some(third_wake.to_string())
        );

        let source = durable_receipt_facts(&events[0]).unwrap();
        let source_state = receipt_ledger_state(&events, &source).unwrap();
        assert_eq!(source_state.review_requested_count, 1);
        assert_eq!(source_state.receipt_count, 1);

        let third = durable_receipt_facts(&events[8]).unwrap();
        let third_state = receipt_ledger_state(&events, &third).unwrap();
        assert_eq!(third_state.review_requested_count, 1);
        assert_eq!(third_state.receipt_count, 0);
    }

    #[test]
    fn b246_broken_supersession_chains_fail_closed_before_latest_wins() {
        let valid = b246_valid_supersession_events();

        let mut self_reference = valid.clone();
        self_reference[4].payload.as_mut().unwrap()["supersededWakeId"] =
            serde_json::json!(B246_SUCCESSOR_WAKE);

        let mut wrong_attempt = valid.clone();
        wrong_attempt[4] = b246_wake_event(
            B246_SUCCESSOR_WAKE,
            "B246-A0002",
            B246_AGENT,
            B246_SUCCESSOR_DIGEST,
            Some(B246_SOURCE_WAKE),
            "opencode",
        );
        wrong_attempt[5] = b246_review_event(
            B246_SUCCESSOR_WAKE,
            "B246-A0002",
            B246_AGENT,
            B246_SUCCESSOR_DIGEST,
        );

        let mut wrong_agent = valid.clone();
        wrong_agent[4] = b246_wake_event(
            B246_SUCCESSOR_WAKE,
            B246_ATTEMPT,
            "executor-opencode-other",
            B246_SUCCESSOR_DIGEST,
            Some(B246_SOURCE_WAKE),
            "opencode",
        );
        wrong_agent[5] = b246_review_event(
            B246_SUCCESSOR_WAKE,
            B246_ATTEMPT,
            "executor-opencode-other",
            B246_SUCCESSOR_DIGEST,
        );

        let mut duplicate_successor = valid.clone();
        let second = "019fc246-dddd-4eee-8fff-000011112222";
        duplicate_successor.push(b246_wake_event(
            second,
            B246_ATTEMPT,
            B246_AGENT,
            B246_SUCCESSOR_DIGEST,
            Some(B246_SOURCE_WAKE),
            "opencode",
        ));
        duplicate_successor.push(b246_review_event(
            second,
            B246_ATTEMPT,
            B246_AGENT,
            B246_SUCCESSOR_DIGEST,
        ));

        let mut missing_death = valid.clone();
        missing_death.remove(3);

        let mut reordered_successor = valid.clone();
        reordered_successor.swap(4, 5);

        let mut missing_deadline = valid.clone();
        missing_deadline[5]
            .payload
            .as_mut()
            .unwrap()
            .as_object_mut()
            .unwrap()
            .remove("deadlineSecs");

        for (label, events) in [
            ("self-reference", self_reference),
            ("wrong-attempt", wrong_attempt),
            ("wrong-agent", wrong_agent),
            ("duplicate-successor", duplicate_successor),
            ("missing-death", missing_death),
            ("reordered-successor", reordered_successor),
            ("missing-deadline", missing_deadline),
        ] {
            let error = active_wakes_from_events(&events, B246_ROUND, B246_AGENT)
                .expect_err("a broken supersession chain must never hide its source");
            assert!(!format!("{error:#}").trim().is_empty(), "case={label}");
        }
    }

