    #[test]
    fn b192_session_receipt_is_first_writer_atomic_private_and_conflict_safe() {
        let root = temp_root("b192-session-receipt");
        fs::create_dir_all(root.join("coordination/runtime")).unwrap();
        let dir = authenticated_supervisor_dir(&root, true).unwrap();
        let wake_id = "019fc192-1111-4222-8333-444455556666";
        let token = "19219219219219219219219219219219";
        let mut sink = ManagedSessionReceiptSink::new(
            &dir,
            wake_id,
            token,
            "executor-opencode",
            "/usr/local/bin/opencode",
        )
        .unwrap();
        let first = r#"{"type":"step_start","sessionID":"ses_b192_first"}"#;
        sink.observe_complete_line(first).unwrap();
        sink.observe_complete_line(first).unwrap();
        let path = dir.join(format!("{token}.session.json"));
        let metadata = fs::symlink_metadata(&path).unwrap();
        assert_eq!(metadata.permissions().mode() & 0o777, 0o600);
        let before = fs::read(&path).unwrap();
        let receipt =
            read_opencode_session_receipt_file(&path, &dir, wake_id, token, "executor-opencode")
                .unwrap();
        assert_eq!(receipt.session_digest, sha256_hex(b"ses_b192_first"));

        let conflict = sink
            .observe_complete_line(r#"{"type":"step_start","sessionID":"ses_b192_conflict"}"#)
            .unwrap_err()
            .to_string();
        assert!(!conflict.contains("ses_b192_first"));
        assert!(!conflict.contains("ses_b192_conflict"));
        assert_eq!(
            fs::read(&path).unwrap(),
            before,
            "first receipt is immutable"
        );
        fs::remove_dir_all(root).unwrap();
    }

