    #[test]
    fn b192_attach_argv_is_exact_and_fork_only_adds_one_flag() {
        let program = Path::new("/private/tmp/bin/opencode");
        let root = Path::new("/private/tmp/review-root");
        let resume = build_opencode_attach_argv(
            program,
            root,
            "fixed continuation prompt",
            "ses_b192_source",
            AttachMode::Resume,
        );
        assert_eq!(
            resume,
            vec![
                "/private/tmp/bin/opencode",
                "run",
                "fixed continuation prompt",
                "--format",
                "json",
                "--dir",
                "/private/tmp/review-root",
                "--session",
                "ses_b192_source",
            ]
        );
        assert_eq!(resume.iter().filter(|arg| *arg == "--session").count(), 1);
        assert!(!resume.iter().any(|arg| arg == "--fork"));
        assert!(!resume
            .iter()
            .any(|arg| matches!(arg.as_str(), "sh" | "bash" | "--continue")));

        let fork = build_opencode_attach_argv(
            program,
            root,
            "fixed continuation prompt",
            "ses_b192_source",
            AttachMode::Fork,
        );
        assert_eq!(&fork[..resume.len()], resume.as_slice());
        assert_eq!(&fork[resume.len()..], &["--fork"]);
    }

    #[test]
    fn b192_attach_source_uses_authenticated_control_and_redacted_ledger() {
        let source = include_str!("wake.rs");
        let start = source
            .find("fn run_managed_wake_attach_inner(")
            .expect("attach implementation");
        let end = source[start..]
            .find("\n/// 纯规划")
            .map(|offset| start + offset)
            .expect("attach implementation boundary");
        let body = &source[start..end];
        assert!(body.contains("request_managed_wake_cancel("));
        for forbidden in ["libc::kill", "killpg(", "Command::new(", "sh -c"] {
            assert!(
                !body.contains(forbidden),
                "forbidden attach authority: {forbidden}"
            );
        }
        let source_terminal = body
            .find("plan_managed_wake_attach(source_wake_id")
            .expect("immutable source terminal gate");
        let launching = body.find("\"launching\"").expect("durable launching phase");
        let spawn = body
            .find("spawn_managed_wake_supervisor_with_binding(")
            .expect("managed continuation spawn");
        assert!(source_terminal < launching && launching < spawn);
        assert!(
            body[..spawn]
                .rfind("formal_review_still_open(")
                .is_some_and(|recheck| recheck > source_terminal),
            "late review must be rechecked after source cleanup and before spawn"
        );
        assert!(
            body[spawn..].contains("formal_review_still_open(events"),
            "review must be rechecked again inside the WakeIssued commit"
        );
        assert!(!body.contains("\"ReviewRequested\""));

        let ledger_start = body.find("let request_digest").expect("ACK ledger block");
        let ledger = &body[ledger_start..];
        assert!(ledger.contains("sessionDigest"));
        assert!(!ledger.contains("source_session.session_id"));
        assert!(!ledger.contains("continuation_session.session_id"));
        assert!(!ledger.contains("\"sessionId\":"));
    }

    #[test]
    fn b192_attach_phase_fold_is_monotonic_and_review_single_flight() {
        let root = temp_root("b192-attach-fold");
        let round = "r192";
        fs::create_dir_all(root.join(format!("coordination/rounds/{round}"))).unwrap();
        fs::create_dir_all(root.join("coordination/runtime")).unwrap();
        fs::write(
            root.join(format!("coordination/rounds/{round}/events.jsonl")),
            "",
        )
        .unwrap();
        let binding = FormalReviewBinding {
            task_id: "B192".to_string(),
            attempt_id: "B192-A0001".to_string(),
            role: "secondary".to_string(),
            agent: "executor-opencode".to_string(),
            continuation_id: "review:r192:B192:B192-A0001:secondary:executor-opencode".to_string(),
            review_path: "coordination/rounds/r192/reviews/review.md".to_string(),
            reviewed_head: "0123456789012345678901234567890123456789".to_string(),
            deadline_secs: 900,
        };
        let source = "019fc192-1111-4222-8333-444455556666";
        let action = attach_action_id(
            round,
            &binding.attempt_id,
            &binding.role,
            source,
            AttachMode::Resume,
        );
        let continuation = stable_uuid_from_material(&action);
        assert_eq!(
            append_attach_phase(
                &root,
                round,
                &binding,
                source,
                &continuation,
                &action,
                AttachMode::Resume,
                "claimed",
                Some("reservation-b192"),
                None,
            )
            .unwrap(),
            1
        );
        assert_eq!(
            append_attach_phase(
                &root,
                round,
                &binding,
                source,
                &continuation,
                &action,
                AttachMode::Resume,
                "claimed",
                Some("reservation-b192"),
                None,
            )
            .unwrap(),
            0
        );
        let fork = attach_action_id(
            round,
            &binding.attempt_id,
            &binding.role,
            source,
            AttachMode::Fork,
        );
        assert!(append_attach_phase(
            &root,
            round,
            &binding,
            source,
            &stable_uuid_from_material(&fork),
            &fork,
            AttachMode::Fork,
            "claimed",
            None,
            None,
        )
        .unwrap_err()
        .to_string()
        .contains("active managed attach writer"));
        for phase in ["source-terminal", "launching", "delivered", "completed"] {
            assert_eq!(
                append_attach_phase(
                    &root,
                    round,
                    &binding,
                    source,
                    &continuation,
                    &action,
                    AttachMode::Resume,
                    phase,
                    None,
                    None,
                )
                .unwrap(),
                1
            );
        }
        let ledger =
            orch_core::read_ledger(&root.join(format!("coordination/rounds/{round}/events.jsonl")))
                .unwrap();
        assert_eq!(
            attach_action_snapshot(&ledger.events, &action)
                .unwrap()
                .unwrap()
                .phase,
            "completed"
        );
        fs::remove_dir_all(root).unwrap();
    }

    fn b307_terminal_status(
        wake_id: &str,
        token: &str,
        runtime_limit: ManagedWakeRuntimeLimit,
    ) -> WakeSupervisorStatus {
        let containment = production_managed_containment(true);
        WakeSupervisorStatus {
            protocol_revision: WAKE_SUPERVISOR_PROTOCOL_REVISION,
            token: token.to_string(),
            wake_id: wake_id.to_string(),
            agent: Some("executor-desktop".to_string()),
            runtime_limit,
            completion_reason: ManagedWakeStopReason::NaturalExit,
            hard_deadline_reached: false,
            cancel_request_id: None,
            cancel_reason: None,
            terminal_seen: true,
            exited_naturally: true,
            signals: Vec::new(),
            containment_capability: containment.capability,
            containment_claim: containment.claim,
            managed_scope_terminated: containment.managed_scope_terminated,
            fork_complete: containment.fork_complete,
            process_tree_terminated: containment.legacy_process_tree_terminated,
            owned_helpers: 0,
            termination_order: Vec::new(),
            ambiguity: Vec::new(),
            exit_status: Some(0),
            error: None,
            topology_snapshots: 1,
            full_credential_inspections: 1,
            log_bytes_read: 0,
            last_frame_age_secs: None,
            last_frame_summary: None,
            elapsed_secs: Some(1),
        }
    }

