    #[test]
    fn b177_wake_fixture_child() {
        let Some(mode) = std::env::var_os(B177_FIXTURE_MODE_ENV) else {
            return;
        };
        // SAFETY: getpgrp has no preconditions and reads this process's actual group.
        let pgid = unsafe { getpgrp() };
        assert!(pgid > 0, "B177 fixture process group must be positive");
        crate::gate::register_gate_fixture(
            std::env::var_os(crate::gate::ORCH_GATE_FIXTURE_REGISTRY).as_deref(),
            std::process::id(),
            pgid as u32,
        )
        .expect("register B177 libtest gate fixture");
        let root = PathBuf::from(
            std::env::var_os(B177_FIXTURE_ROOT_ENV).expect("activated B177 fixture lacks root env"),
        );
        let ready = std::env::var_os(B177_FIXTURE_READY_ENV).map(PathBuf::from);
        run_b177_wake_fixture(&root, &mode.to_string_lossy(), ready.as_deref())
            .expect("B177 libtest fixture failed");
    }

    #[test]
    fn b177_wake_fixture_stubborn_provider_child() {
        let executable = std::env::current_exe().expect("resolve copied libtest executable");
        if executable.file_name().and_then(|name| name.to_str()) != Some("opencode") {
            return;
        }
        // SAFETY: getpgrp has no preconditions and reads this process's actual group.
        let pgid = unsafe { getpgrp() };
        assert!(pgid > 0, "stubborn provider process group must be positive");
        crate::gate::register_gate_fixture(
            std::env::var_os(crate::gate::ORCH_GATE_FIXTURE_REGISTRY).as_deref(),
            std::process::id(),
            pgid as u32,
        )
        .expect("register stubborn provider gate fixture");
        let root = std::env::current_dir().expect("resolve copied libtest provider cwd");
        run_b177_wake_fixture(&root, "provider-stubborn", None)
            .expect("fixed stubborn provider fixture failed");
    }

    #[test]
    fn b260_wake_fixture_deadline_provider_child() {
        let executable = std::env::current_exe().expect("resolve copied libtest executable");
        if executable.file_name().and_then(|name| name.to_str()) != Some("opencode") {
            return;
        }
        // SAFETY: getpgrp has no preconditions and reads this process's actual group.
        let pgid = unsafe { getpgrp() };
        assert!(pgid > 0, "deadline provider process group must be positive");
        crate::gate::register_gate_fixture(
            std::env::var_os(crate::gate::ORCH_GATE_FIXTURE_REGISTRY).as_deref(),
            std::process::id(),
            pgid as u32,
        )
        .expect("register deadline provider gate fixture");
        b177_ignore_fixture_signal(1).expect("ignore SIGHUP in deadline provider");
        b177_ignore_fixture_signal(15).expect("ignore SIGTERM in deadline provider");
        let frame = serde_json::json!({
            "type": "text",
            "part": {"type": "text", "text": B260_LAST_FRAME_MARKER},
        });
        let mut stdout = std::io::stdout().lock();
        // libtest writes a non-LF prefix before the body. Begin a fresh frame.
        writeln!(stdout).unwrap();
        writeln!(stdout, "{frame}").unwrap();
        stdout.flush().unwrap();
        loop {
            std::thread::sleep(Duration::from_secs(60));
        }
    }

    #[test]
    fn b177_libtest_fixture_emits_an_independent_terminal_record() {
        let root = temp_root("libtest-terminal-record");
        fs::create_dir_all(&root).unwrap();
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let mut command = b177_fixture_command(&root, "provider-natural", None);
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        assert!(command.status().unwrap().success());

        let log = fs::read_to_string(&log_path).unwrap();
        let terminal_lines = log
            .lines()
            .filter(|line| {
                classify_managed_terminal("opencode", line) == ManagedTerminal::OpenCodeStop
            })
            .collect::<Vec<_>>();
        assert_eq!(terminal_lines.len(), 1, "log={log:?}");
        assert_eq!(terminal_lines[0].as_bytes(), B177_FIXTURE_TERMINAL_RECORD);
        serde_json::from_str::<serde_json::Value>(terminal_lines[0]).unwrap();
        fs::remove_dir_all(root).unwrap();
    }

