    #[derive(Debug, Clone, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct DetachedSupervisorMarker {
        supervisor: ManagedProcessCredential,
        provider: ManagedProcessCredential,
    }

    struct DetachedSupervisorGuard {
        launcher: Option<Child>,
        marker: Option<DetachedSupervisorMarker>,
    }

    struct B177ForgedAckArm;

    impl B177ForgedAckArm {
        fn new(phase: B177ForgedAckPhase) -> Self {
            assert!(
                B177_FORGED_ACK_PHASE.with(|slot| slot.get()).is_none(),
                "forged-ACK phase hook was already armed"
            );
            assert!(
                B177_FORGED_ACK_CAPTURE.with(|slot| slot.borrow().is_none()),
                "forged-ACK capture leaked from a prior scene"
            );
            B177_FORGED_ACK_PHASE.with(|slot| slot.set(Some(phase)));
            Self
        }

        fn try_capture(&self) -> Option<B177ForgedAckCapture> {
            B177_FORGED_ACK_CAPTURE.with(|slot| slot.borrow().clone())
        }
    }

    impl Drop for B177ForgedAckArm {
        fn drop(&mut self) {
            B177_FORGED_ACK_PHASE.with(|slot| slot.set(None));
            B177_FORGED_ACK_CAPTURE.with(|slot| {
                slot.borrow_mut().take();
            });
        }
    }

    #[test]
    fn b190_exact_hidden_supervisor_command_validation_is_fail_closed() {
        let program = "/repo/.worktrees/B177-secondary-executor-opencode/orch/target/debug/orch";
        let root = "/repo/.worktrees/B177-secondary-executor-opencode/target/test root";
        let exact = format!("{program} --root {root} __wake-supervise");
        validate_hidden_supervisor_command_line_for_test(&exact, program, root).unwrap();
        validate_hidden_supervisor_command_line_for_test(&format!("\t {exact}\r\n"), program, root)
            .unwrap();

        for observed in [
            format!("/wrong/orch --root {root} __wake-supervise"),
            format!("{program} --root /wrong/root __wake-supervise"),
            format!("{program} --root {root} status"),
            format!("{program} --root {root}"),
            format!("{exact} opencode"),
            exact[..exact.len() - 1].to_string(),
            format!("{program}\n --root {root} __wake-supervise"),
        ] {
            let error = validate_hidden_supervisor_command_line_for_test(&observed, program, root)
                .expect_err("non-exact supervisor command must fail closed");
            assert!(error.contains("expected="), "error={error}");
            assert!(error.contains("observed="), "error={error}");
        }

        for ambiguous in [" bad", "bad ", "bad\npath", "bad\rpath", "bad\0path"] {
            assert!(
                validate_hidden_supervisor_command_line_for_test(&exact, ambiguous, root).is_err()
            );
            assert!(
                validate_hidden_supervisor_command_line_for_test(&exact, program, ambiguous)
                    .is_err()
            );
        }
        assert!(validate_hidden_supervisor_command_line_for_test("", program, root).is_err());

        let long_observed = format!("{exact} {}", "secret-prompt".repeat(10_000));
        let error = validate_hidden_supervisor_command_line_for_test(&long_observed, program, root)
            .unwrap_err();
        assert!(
            error.len() < 512,
            "diagnostic was not bounded: {}",
            error.len()
        );
    }

    #[test]
    fn b190_missing_fresh_binary_causal_chain_survives_missing_capture() {
        let prerequisite = anyhow::anyhow!("No such file or directory")
            .context("stat test orch binary failed: /isolated/target/debug/orch");
        let rendered = format!("{prerequisite:#}");
        let arm = B177ForgedAckArm::new(B177ForgedAckPhase::Offer);
        let diagnostic = require_test_hook_capture_or_explain::<B177ForgedAckCapture>(
            "B177 forged-ACK hook",
            arm.try_capture(),
            Some(&rendered),
        )
        .expect_err("a spawn prerequisite cannot produce hook receipts");
        assert!(diagnostic.contains("B177 forged-ACK hook"));
        assert!(diagnostic.contains("stat test orch binary failed"));
        assert!(diagnostic.contains("No such file or directory"));
        drop(arm);
    }

    #[test]
    fn b190_hook_capture_wins_only_after_diagnostics_are_well_formed() {
        struct Receipt;

        assert!(require_test_hook_capture_or_explain(
            "B177 forged-ACK hook",
            Some(Receipt),
            Some("wake supervisor ack identity mismatch"),
        )
        .is_ok());
        let invariant =
            require_test_hook_capture_or_explain::<Receipt>("B177 forged-ACK hook", None, None);
        let invariant = match invariant {
            Err(error) => error,
            Ok(_) => panic!("missing capture unexpectedly returned a receipt"),
        };
        assert!(invariant.contains("without observing"));
        assert!(
            require_test_hook_capture_or_explain(" ", Some(Receipt), None).is_err(),
            "a capture must not hide an invalid hook name"
        );
        assert!(require_test_hook_capture_or_explain(
            "B177 forged-ACK hook",
            Some(Receipt),
            Some(" \n")
        )
        .is_err());
    }

    #[derive(Debug, Clone, Serialize, Deserialize)]
    #[serde(rename_all = "camelCase")]
    struct B177FailureMetaMarker {
        provider: ManagedProcessCredential,
        helper: ManagedProcessCredential,
    }

    #[derive(Debug)]
    struct B177FailureMetaCleanupEvidence {
        helper_before_scenario_reap: B177LatestDisposition,
        provider_before_scenario_reap: B177LatestDisposition,
        helper_after_scenario_reap: B177LatestDisposition,
        provider_after_scenario_reap: B177LatestDisposition,
        scenario_after_reap: B177LatestDisposition,
        diagnostics: Vec<String>,
    }

    /// Outer owner for the one failure-path meta regression. The inner
    /// libtest process can block, panic, or lose its local JoinHandle, but the
    /// outer process retains the exact scenario Child plus immutable provider
    /// and helper receipts published before the failure scene starts.
    struct B177FailureMetaOuterGuard {
        scenario: Option<Child>,
        scenario_receipt: ManagedProcessCredential,
        marker: Option<B177FailureMetaMarker>,
    }

    impl B177FailureMetaOuterGuard {
        fn new(scenario: Child) -> Result<Self> {
            let scenario_receipt = inspect_stable_process(scenario.id())?
                .context("failure-meta scenario lacks a stable launch receipt")?;
            Ok(Self {
                scenario: Some(scenario),
                scenario_receipt,
                marker: None,
            })
        }

        fn scenario_status_until(&mut self, deadline: Instant) -> Result<Option<ExitStatus>> {
            let Some(scenario) = self.scenario.as_mut() else {
                return Ok(None);
            };
            let status = scenario
                .wait_timeout(deadline.saturating_duration_since(Instant::now()))
                .context("wait for failure-meta inner scenario")?;
            if status.is_some() {
                self.scenario.take();
            }
            Ok(status)
        }

        fn validate_and_install_marker(&mut self, marker: B177FailureMetaMarker) -> Result<()> {
            let scenario = self
                .scenario
                .as_ref()
                .context("failure-meta scenario Child is no longer owned")?;
            if scenario.id() != self.scenario_receipt.pid {
                bail!("failure-meta scenario Child/receipt pid mismatch");
            }
            let scenario_now = inspect_stable_process(self.scenario_receipt.pid)?
                .context("failure-meta scenario receipt is no longer current")?;
            if scenario_now != self.scenario_receipt {
                bail!("failure-meta scenario receipt changed before sidecar admission");
            }
            if BTreeSet::from([
                self.scenario_receipt.pid,
                marker.provider.pid,
                marker.helper.pid,
            ])
            .len()
                != 3
            {
                bail!("failure-meta scenario/provider/helper pids must be distinct");
            }
            if marker.provider.pid != marker.provider.pgid
                || marker.provider.pid != marker.provider.sid
                || marker.provider.observed_ppid != self.scenario_receipt.pid
                || marker.provider.uid != self.scenario_receipt.uid
            {
                bail!("failure-meta provider receipt lacks exact scenario provenance");
            }
            if marker.helper.pid != marker.helper.pgid
                || marker.helper.pid != marker.helper.sid
                || marker.helper.observed_ppid != marker.provider.pid
                || marker.helper.uid != marker.provider.uid
            {
                bail!("failure-meta helper receipt lacks exact provider provenance");
            }
            for pass in 1..=2 {
                let provider_now = inspect_stable_process(marker.provider.pid)?
                    .with_context(|| format!("failure-meta provider missing in pass {pass}"))?;
                if provider_now != marker.provider {
                    bail!("failure-meta provider changed in provenance pass {pass}");
                }
            }
            for pass in 1..=2 {
                let helper_now = inspect_stable_process(marker.helper.pid)?
                    .with_context(|| format!("failure-meta helper missing in pass {pass}"))?;
                if helper_now != marker.helper {
                    bail!("failure-meta helper changed in provenance pass {pass}");
                }
            }
            self.marker = Some(marker);
            Ok(())
        }

        fn cleanup_until(&mut self, deadline: Instant) -> B177FailureMetaCleanupEvidence {
            let mut diagnostics = Vec::new();
            let mut helper_before_scenario_reap = B177LatestDisposition::LiveOrAmbiguous;
            let mut provider_before_scenario_reap = B177LatestDisposition::LiveOrAmbiguous;
            if let Some(marker) = self.marker.as_ref() {
                let helper_owned = BTreeMap::from([(marker.helper.pid, marker.helper.clone())]);
                let helper_deadline = deadline
                    .checked_sub(Duration::from_millis(1_500))
                    .unwrap_or(deadline);
                if Instant::now() < helper_deadline {
                    match run_exact_group_watchdog(
                        marker.helper.pgid,
                        &helper_owned,
                        helper_deadline,
                    ) {
                        Ok(evidence) => {
                            let group = evidence.latest_disposition();
                            diagnostics.push(format!("outer helper {}", evidence.summary()));
                            helper_before_scenario_reap = b177_harden_group_with_fresh_epoch(
                                "outer helper",
                                group,
                                std::slice::from_ref(&marker.helper),
                                &mut diagnostics,
                            );
                        }
                        Err(error) => {
                            diagnostics.push(format!("outer helper watchdog error: {error:#}"))
                        }
                    }
                }
                let provider_deadline = deadline
                    .checked_sub(Duration::from_millis(500))
                    .unwrap_or(deadline);
                if matches!(
                    helper_before_scenario_reap,
                    B177LatestDisposition::Gone | B177LatestDisposition::ZombiePendingProviderReap
                ) && Instant::now() < provider_deadline
                {
                    let provider_owned =
                        BTreeMap::from([(marker.provider.pid, marker.provider.clone())]);
                    match run_exact_group_watchdog(
                        marker.provider.pgid,
                        &provider_owned,
                        provider_deadline,
                    ) {
                        Ok(evidence) => {
                            let group = evidence.latest_disposition();
                            diagnostics.push(format!("outer provider {}", evidence.summary()));
                            provider_before_scenario_reap = b177_harden_group_with_fresh_epoch(
                                "outer provider",
                                group,
                                std::slice::from_ref(&marker.provider),
                                &mut diagnostics,
                            );
                        }
                        Err(error) => {
                            diagnostics.push(format!("outer provider watchdog error: {error:#}"))
                        }
                    }
                } else {
                    diagnostics.push(format!(
                        "outer provider blocked by helper disposition {helper_before_scenario_reap:?}"
                    ));
                }
            } else {
                diagnostics.push("failure-meta marker was never published".into());
            }

            let exact_groups_allow_scenario_reap = matches!(
                helper_before_scenario_reap,
                B177LatestDisposition::Gone | B177LatestDisposition::ZombiePendingProviderReap
            ) && matches!(
                provider_before_scenario_reap,
                B177LatestDisposition::Gone | B177LatestDisposition::ZombiePendingProviderReap
            );
            if exact_groups_allow_scenario_reap {
                let mut scenario_reaped = false;
                if let Some(scenario) = self.scenario.as_mut() {
                    match scenario.try_wait() {
                        Ok(Some(_)) => scenario_reaped = true,
                        Ok(None) if Instant::now() >= deadline => diagnostics.push(
                            "scenario kill refused after the absolute cleanup deadline".into(),
                        ),
                        Ok(None) => match scenario.kill() {
                            Ok(()) => match scenario.wait() {
                                Ok(_) => scenario_reaped = true,
                                Err(error) => diagnostics.push(format!(
                                    "scenario wait after successful kill failed; Child retained: {error}"
                                )),
                            },
                            Err(error) => diagnostics.push(format!(
                                "scenario kill failed; Child retained: {error}"
                            )),
                        },
                        Err(error) => diagnostics.push(format!(
                            "scenario try_wait failed; Child retained: {error}"
                        )),
                    }
                }
                if scenario_reaped {
                    self.scenario.take();
                }
            } else if self.scenario.is_some() {
                diagnostics.push(
                    "scenario Child retained because exact helper/provider cleanup is not authorized"
                        .into(),
                );
            }

            let marker = self.marker.as_ref();
            let helper_after_scenario_reap =
                marker.map_or(B177LatestDisposition::LiveOrAmbiguous, |marker| {
                    b177_fresh_epoch_retirement_until(
                        std::slice::from_ref(&marker.helper),
                        deadline,
                    )
                });
            let provider_after_scenario_reap =
                marker.map_or(B177LatestDisposition::LiveOrAmbiguous, |marker| {
                    b177_fresh_epoch_retirement_until(
                        std::slice::from_ref(&marker.provider),
                        deadline,
                    )
                });
            let scenario_after_reap = b177_fresh_epoch_retirement_until(
                std::slice::from_ref(&self.scenario_receipt),
                deadline,
            );
            B177FailureMetaCleanupEvidence {
                helper_before_scenario_reap,
                provider_before_scenario_reap,
                helper_after_scenario_reap,
                provider_after_scenario_reap,
                scenario_after_reap,
                diagnostics,
            }
        }

        fn disarm(&mut self) {
            self.scenario = None;
            self.marker = None;
        }
    }

    impl Drop for B177FailureMetaOuterGuard {
        fn drop(&mut self) {
            while self.scenario.is_some() || self.marker.is_some() {
                let evidence = self.cleanup_until(Instant::now() + Duration::from_secs(5));
                let old_epochs_gone = evidence.helper_after_scenario_reap
                    == B177LatestDisposition::Gone
                    && evidence.provider_after_scenario_reap == B177LatestDisposition::Gone
                    && evidence.scenario_after_reap == B177LatestDisposition::Gone;
                if old_epochs_gone {
                    self.scenario = None;
                    self.marker = None;
                    break;
                }
                if let Some(scenario) = self.scenario.as_mut() {
                    // Fail closed: retain the unique Child and wait
                    // synchronously when exact helper/provider authority is
                    // still ambiguous. The outer test runner, not a detached
                    // thread or dropped Child, owns the hard timeout report.
                    match scenario.wait() {
                        Ok(_) => {
                            self.scenario.take();
                        }
                        Err(_) => {
                            // A failed wait does not transfer or discharge
                            // Child custody. Retain it for the next exact
                            // cleanup iteration.
                            std::thread::sleep(Duration::from_millis(5));
                        }
                    }
                } else {
                    // The scenario is already reaped but an external exact
                    // epoch is not. Keep retrying read/prove/signal stages;
                    // never discard the immutable sidecar authority.
                    std::thread::sleep(Duration::from_millis(5));
                }
            }
        }
    }

    impl DetachedSupervisorGuard {
        fn kill_launcher_group(&mut self) {
            let Some(mut launcher) = self.launcher.take() else {
                return;
            };
            let pgid = i32::try_from(launcher.id()).unwrap();
            // SAFETY: the test spawned this exact child with process_group(0),
            // so the negative PID names only the disposable launcher group.
            let result = unsafe { libc_kill(-pgid, 9) };
            assert_eq!(result, 0, "kill isolated launcher group failed");
            launcher.wait().unwrap();
        }

        fn kill_if_same_epoch(receipt: &ManagedProcessCredential) {
            let Some(topology) = inspect_topology(receipt.pid).ok().flatten() else {
                return;
            };
            if !receipt_immutable_matches_topology(receipt, &topology)
                || topology.pgid != receipt.pgid
                || topology.sid != receipt.sid
            {
                return;
            }
            let Ok(pid) = i32::try_from(receipt.pid) else {
                return;
            };
            // SAFETY: the immutable PID/UID/birth receipt and current PGID/SID
            // were revalidated immediately above. This single-process cleanup
            // is reserved for the hidden supervisor after its provider is
            // proven gone; provider groups use the exact receipt watchdog.
            let _ = unsafe { libc_kill(pid, 9) };
        }
    }

    impl Drop for DetachedSupervisorGuard {
        fn drop(&mut self) {
            if let Some(mut launcher) = self.launcher.take() {
                let pgid = i32::try_from(launcher.id()).unwrap();
                // SAFETY: see kill_launcher_group.
                let _ = unsafe { libc_kill(-pgid, 9) };
                let _ = launcher.wait();
            }
            if let Some(marker) = &self.marker {
                let deadline = Instant::now() + Duration::from_secs(2);
                let provider_owned =
                    BTreeMap::from([(marker.provider.pid, marker.provider.clone())]);
                let mut provider_gone =
                    run_exact_group_watchdog(marker.provider.pgid, &provider_owned, deadline)
                        .is_ok_and(|evidence| evidence.esrch);
                while inspect_topology(marker.provider.pid)
                    .ok()
                    .flatten()
                    .is_some_and(|topology| {
                        receipt_immutable_matches_topology(&marker.provider, &topology)
                    })
                    && Instant::now() < deadline
                {
                    std::thread::sleep(Duration::from_millis(5));
                }
                provider_gone |= inspect_topology(marker.provider.pid)
                    .ok()
                    .flatten()
                    .is_none_or(|topology| {
                        !receipt_immutable_matches_topology(&marker.provider, &topology)
                    });
                if provider_gone {
                    Self::kill_if_same_epoch(&marker.supervisor);
                }
            }
        }
    }

    #[test]
    fn b177_detached_supervisor_launcher_child() {
        let Some(root) = std::env::var_os("ORCH_B177_DETACHED_LAUNCHER_ROOT") else {
            return;
        };
        let root = PathBuf::from(root);
        let logs = root.join("coordination/runtime/logs");
        let supervisors = root.join("coordination/runtime/supervisors");
        let bin = root.join("bin");
        fs::create_dir_all(&logs).unwrap();
        fs::create_dir_all(&supervisors).unwrap();
        fs::create_dir_all(&bin).unwrap();
        let program = bin.join("opencode");
        fs::copy(std::env::current_exe().unwrap(), &program).unwrap();
        fs::set_permissions(&program, fs::Permissions::from_mode(0o755)).unwrap();
        let log_path = logs.join("wake-opencode.jsonl");
        File::create(&log_path).unwrap();
        let argv = vec![
            program.to_string_lossy().into_owned(),
            "--exact".to_string(),
            B177_STUBBORN_PROVIDER_TEST.to_string(),
            "--nocapture".to_string(),
            "--test-threads=1".to_string(),
        ];
        let provider_pid = spawn_managed_wake_supervisor(
            &root,
            "executor-opencode",
            &argv,
            &log_path,
            &fresh_managed_wake_id(),
            managed_wake_runtime_limit(None),
            &BTreeMap::new(),
            None,
        )
        .unwrap();
        let provider =
            capture_provider_credential(&mut ProcessObserver::default(), provider_pid).unwrap();
        let supervisor_candidates = process_topology_snapshot()
            .unwrap()
            .into_values()
            .filter(|topology| {
                topology.observed_ppid == std::process::id()
                    && topology.pgid == topology.pid
                    && topology.sid == topology.pid
            })
            .map(|topology| topology.pid)
            .collect::<Vec<_>>();
        assert_eq!(
            supervisor_candidates.len(),
            1,
            "launcher must own exactly one isolated supervisor"
        );
        let supervisor = inspect_stable_process(supervisor_candidates[0])
            .unwrap()
            .unwrap();
        let marker = DetachedSupervisorMarker {
            supervisor,
            provider,
        };
        atomic_create_json(&root.join("launcher-marker.json"), &marker).unwrap();
        loop {
            std::thread::sleep(Duration::from_secs(60));
        }
    }

    #[test]
    fn b177_detached_supervisor_survives_parent_group_kill_and_reaps_provider() {
        let root = temp_root("detached-supervisor-parent-kill");
        fs::create_dir_all(&root).unwrap();
        let mut launcher_command = Command::new(std::env::current_exe().unwrap());
        launcher_command
            .args([
                "--exact",
                "wake::tests::b177_detached_supervisor_launcher_child",
                "--nocapture",
                "--test-threads=1",
            ])
            .env("ORCH_B177_DETACHED_LAUNCHER_ROOT", &root)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0);
        let launcher = launcher_command.spawn().unwrap();
        let mut guard = DetachedSupervisorGuard {
            launcher: Some(launcher),
            marker: None,
        };
        let marker_path = root.join("launcher-marker.json");
        let marker_deadline = Instant::now() + Duration::from_secs(10);
        while !marker_path.is_file() && Instant::now() < marker_deadline {
            assert!(
                guard
                    .launcher
                    .as_mut()
                    .and_then(|launcher| launcher.try_wait().ok())
                    .flatten()
                    .is_none(),
                "launcher exited before publishing detached custody receipt"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
        assert!(marker_path.is_file(), "launcher receipt timed out");
        guard.marker = Some(serde_json::from_slice(&fs::read(&marker_path).unwrap()).unwrap());
        let marker = guard.marker.as_ref().unwrap().clone();
        assert_eq!(marker.supervisor.pgid, marker.supervisor.pid);
        assert_eq!(marker.supervisor.sid, marker.supervisor.pid);
        guard.kill_launcher_group();

        let status_deadline = Instant::now() + Duration::from_secs(12);
        let status_path = loop {
            let status = fs::read_dir(root.join("coordination/runtime/supervisors"))
                .unwrap()
                .filter_map(|entry| entry.ok())
                .map(|entry| entry.path())
                .find(|path| {
                    path.file_name()
                        .and_then(|name| name.to_str())
                        .is_some_and(|name| name.ends_with(".status.json"))
                });
            if status.is_some() || Instant::now() >= status_deadline {
                break status;
            }
            std::thread::sleep(Duration::from_millis(10));
        }
        .expect("detached supervisor did not close provider after parent group death");
        let status: serde_json::Value =
            serde_json::from_slice(&fs::read(status_path).unwrap()).unwrap();
        assert_eq!(status["terminalSeen"], true);
        assert_eq!(status["signals"], serde_json::json!(["TERM", "KILL"]));
        assert_eq!(status["containmentCapability"], "observed-receipted");
        assert_eq!(status["containmentClaim"], "managed-scope-terminated");
        assert_eq!(status["managedScopeTerminated"], true);
        assert_eq!(status["forkComplete"], false);
        assert_eq!(status["processTreeTerminated"], false);
        let gone_deadline = Instant::now() + Duration::from_secs(2);
        while (inspect_topology(marker.provider.pid).unwrap().is_some()
            || inspect_topology(marker.supervisor.pid).unwrap().is_some())
            && Instant::now() < gone_deadline
        {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(inspect_topology(marker.provider.pid).unwrap().is_none());
        assert!(inspect_topology(marker.supervisor.pid).unwrap().is_none());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_parent_rejects_forged_offer_and_accepted_revision_without_orphans() {
        const B203_TRIAL_GATE_SAMPLES: usize = 10;
        let mut completed = 0;
        for sample in 0..B203_TRIAL_GATE_SAMPLES {
            b203_h84_one_sample(sample);
            completed += 1;
        }
        assert_eq!(completed, 10, "H84 trial-gate samples completed");
    }

    fn b203_h84_one_sample(sample: usize) {
        for phase in [B177ForgedAckPhase::Offer, B177ForgedAckPhase::Accepted] {
            let label = match phase {
                B177ForgedAckPhase::Offer => "offer",
                B177ForgedAckPhase::Accepted => "accepted",
            };
            let root = temp_root(&format!("forged-{label}-revision-sample-{sample}"));
            let logs = root.join("coordination/runtime/logs");
            let supervisors = root.join("coordination/runtime/supervisors");
            let bin = root.join("bin");
            fs::create_dir_all(&logs).unwrap();
            fs::create_dir_all(&supervisors).unwrap();
            fs::create_dir_all(&bin).unwrap();
            let program = bin.join("opencode");
            fs::copy(std::env::current_exe().unwrap(), &program).unwrap();
            fs::set_permissions(&program, fs::Permissions::from_mode(0o755)).unwrap();
            let log_path = logs.join("wake-opencode.jsonl");
            File::create(&log_path).unwrap();
            let argv = vec![
                program.to_string_lossy().into_owned(),
                "--exact".to_string(),
                B177_STUBBORN_PROVIDER_TEST.to_string(),
                "--nocapture".to_string(),
                "--test-threads=1".to_string(),
            ];

            let arm = B177ForgedAckArm::new(phase);
            let result = spawn_managed_wake_supervisor(
                &root,
                "executor-opencode",
                &argv,
                &log_path,
                &fresh_managed_wake_id(),
                managed_wake_runtime_limit(None),
                &BTreeMap::new(),
                None,
            );
            let spawn_error = result.as_ref().err().map(|error| format!("{error:#}"));
            let capture = require_test_hook_capture_or_explain(
                "B177 forged-ACK hook",
                arm.try_capture(),
                spawn_error.as_deref(),
            )
            .unwrap_or_else(|diagnostic| panic!("{diagnostic}"));
            let status_path = supervisors.join(format!("{}.status.json", capture.token));
            let mut fallback = DetachedSupervisorGuard {
                launcher: None,
                marker: Some(DetachedSupervisorMarker {
                    supervisor: capture.supervisor.clone(),
                    provider: capture.provider.clone(),
                }),
            };

            let deadline = Instant::now() + Duration::from_secs(15);
            loop {
                let provider_state = b177_fresh_epoch_retirement_disposition(std::slice::from_ref(
                    &capture.provider,
                ))
                .unwrap_or(B177LatestDisposition::LiveOrAmbiguous);
                let supervisor_state = b177_fresh_epoch_retirement_disposition(
                    std::slice::from_ref(&capture.supervisor),
                )
                .unwrap_or(B177LatestDisposition::LiveOrAmbiguous);
                if provider_state == B177LatestDisposition::Gone
                    && supervisor_state == B177LatestDisposition::Gone
                    && status_path.is_file()
                {
                    break;
                }
                assert!(
                    Instant::now() < deadline,
                    "phase={phase:?} provider={provider_state:?} supervisor={supervisor_state:?} statusExists={}",
                    status_path.is_file()
                );
                std::thread::sleep(Duration::from_millis(5));
            }
            let status: serde_json::Value =
                serde_json::from_slice(&fs::read(&status_path).unwrap()).unwrap();
            assert_eq!(
                status["containmentClaim"], "managed-scope-terminated",
                "phase={phase:?} status={status:?}"
            );
            assert_eq!(status["managedScopeTerminated"], true);
            assert_eq!(status["forkComplete"], false);
            assert_eq!(status["processTreeTerminated"], false);
            fallback.marker = None;

            let error = result.expect_err("parent accepted a forged ACK protocol revision");
            let rendered = format!("{error:#}");
            match phase {
                B177ForgedAckPhase::Offer => assert!(
                    rendered.contains("wake supervisor ack identity mismatch"),
                    "unexpected OFFER rejection: {rendered}"
                ),
                B177ForgedAckPhase::Accepted => assert!(
                    rendered.contains("wake supervisor ACCEPTED identity mismatch"),
                    "unexpected ACCEPTED rejection: {rendered}"
                ),
            }
            drop(fallback);
            drop(arm);
            // H84 (planner test-only stabilization, r62/B204): the exact-Child
            // reaper publishes `<token>.reap.json` asynchronously, so removing
            // the sample root immediately races a late sidecar write and yields
            // ErrorKind::DirectoryNotEmpty. Wait for every registered sidecar to
            // reach its terminal state first. This does not weaken any orphan
            // assertion: the wait panics loudly if a reaper never settles, so a
            // genuinely stuck reaper still reddens this test.
            b204_wait_for_reap_sidecars_terminal(&supervisors, sample, label);
            fs::remove_dir_all(root).unwrap();
        }
    }

    /// Block until every `*.reap.json` under `supervisor_dir` reports a terminal
    /// state. Loud on timeout — never silently proceeds to teardown.
    fn b204_wait_for_reap_sidecars_terminal(supervisor_dir: &Path, sample: usize, label: &str) {
        let deadline = Instant::now() + Duration::from_secs(30);
        loop {
            let mut waiting = Vec::new();
            let mut observed = 0_usize;
            if let Ok(entries) = fs::read_dir(supervisor_dir) {
                for entry in entries.flatten() {
                    let name = entry.file_name();
                    let name = name.to_string_lossy().into_owned();
                    if !name.ends_with(".reap.json") {
                        continue;
                    }
                    observed += 1;
                    let Ok(bytes) = fs::read(entry.path()) else {
                        waiting.push(format!("{name}:unreadable"));
                        continue;
                    };
                    let Ok(value) = serde_json::from_slice::<serde_json::Value>(&bytes) else {
                        waiting.push(format!("{name}:unparsed"));
                        continue;
                    };
                    match value["state"].as_str() {
                        Some("reaped") => {}
                        other => waiting.push(format!("{name}:{other:?}")),
                    }
                }
            }
            if waiting.is_empty() {
                let _ = observed;
                return;
            }
            assert!(
                Instant::now() < deadline,
                "H84 sample={sample} phase={label}: reap sidecars never reached a terminal state: \
                 observed={observed} waiting={waiting:?}"
            );
            std::thread::sleep(Duration::from_millis(10));
        }
    }

    #[test]
    fn b177_failure_cleanup_no_terminal_zombie_inner() {
        let Some(root) = std::env::var_os(B177_FAILURE_META_ROOT_ENV) else {
            return;
        };
        let root = PathBuf::from(root);
        fs::create_dir_all(&root).unwrap();
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let ready = root.join("ready");
        let helper_ready = ready.join("helper-ready");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command =
            b177_fixture_command(&root, "provider-cross-pgid-sticky-zombie", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, vec![helper_ready.clone()]);
        let provider = inspect_stable_process(fixture.provider_pgid)
            .unwrap()
            .expect("meta provider lacks stable credential");
        wait_for_fixture_file(
            &helper_ready,
            Instant::now() + Duration::from_secs(5),
            "meta helper receipt",
        )
        .unwrap();
        let helper_pid = fs::read_to_string(&helper_ready)
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        let helper = inspect_stable_process(helper_pid)
            .unwrap()
            .expect("meta helper lacks stable credential");
        assert_eq!(helper.observed_ppid, provider.pid);
        assert_ne!(helper.pgid, provider.pgid);
        fixture.register_helper_receipt(helper.clone()).unwrap();
        let admission_path = root.join("failure-meta-admitted");
        let transfer_path = root.join("failure-meta-transferred");
        assert!(
            !admission_path.exists(),
            "failure-meta admission ACK must start absent"
        );
        assert!(
            !transfer_path.exists(),
            "failure-meta transfer marker must start absent"
        );
        atomic_create_json(
            &root.join("failure-meta-marker.json"),
            &B177FailureMetaMarker {
                provider: provider.clone(),
                helper: helper.clone(),
            },
        )
        .unwrap();
        let admission_deadline = Instant::now() + Duration::from_secs(5);
        loop {
            match fs::read(&admission_path) {
                Ok(bytes) => {
                    assert_eq!(bytes, b"admitted\n", "failure-meta ACK must be exact");
                    break;
                }
                Err(error) if error.kind() == io::ErrorKind::NotFound => {}
                Err(error) => panic!("failure-meta ACK read failed: {error}"),
            }
            assert!(
                Instant::now() < admission_deadline,
                "failure-meta admission ACK timed out while fixture guard remained armed"
            );
            std::thread::sleep(Duration::from_millis(5));
        }

        let policy = WakeSupervisorPolicy {
            natural_exit_grace_ms: 50,
            term_grace_ms: 30,
            poll_interval_ms: 5,
        };
        let (done_tx, done_rx) = std::sync::mpsc::sync_channel(1);
        let supervised_provider = provider.clone();
        let child = fixture.take_child_after_exact_admission(&admission_path, &transfer_path);
        let mut supervisor = Some(std::thread::spawn({
            let log_path = log_path.clone();
            move || {
                let result = supervise_managed_child_with_baseline(
                    child,
                    "opencode",
                    &log_path,
                    policy,
                    baseline,
                    Some(supervised_provider),
                    None,
                    true,
                    ProcessObserver::default(),
                );
                let _ = done_tx.send(result);
            }
        }));
        fs::write(ready.join("release-helper"), b"release\n").unwrap();
        let zombie_deadline = Instant::now() + Duration::from_secs(5);
        loop {
            match inspect_opaque_zombie(helper.pid) {
                Ok(Some(zombie)) => {
                    assert!(
                        owned_zombie_epoch_matches_receipt(&helper, &zombie)
                            && zombie.observed_ppid == provider.pid
                            && zombie.pgid == helper.pgid,
                        "meta helper zombie changed exact birth/ppid/pgid"
                    );
                    break;
                }
                Ok(None) => {}
                Err(error) if error.to_string().contains("proved a live process") => {}
                Err(error) => panic!("{:#}", error.context("inspect failure-meta helper zombie")),
            }
            assert!(
                Instant::now() < zombie_deadline,
                "meta helper did not become the exact owned zombie"
            );
            std::thread::sleep(Duration::from_millis(5));
        }

        let started = Instant::now();
        let mut helper_receipt = Some(helper);
        let cleanup = b177_bounded_fixture_failure_cleanup(
            "meta no-terminal/zombie-helper",
            &[ready.join("release-helper")],
            Some(&helper_ready),
            &mut helper_receipt,
            &provider,
            policy,
            &done_rx,
            &mut supervisor,
        );
        assert!(cleanup.joined, "cleanup={:?}", cleanup.diagnostics);
        assert_eq!(
            cleanup.helper_before_join,
            B177LatestDisposition::ZombiePendingProviderReap,
            "cleanup={:?}",
            cleanup.diagnostics
        );
        assert!(matches!(
            cleanup.provider_before_join,
            B177LatestDisposition::Gone | B177LatestDisposition::ZombiePendingProviderReap
        ));
        assert_eq!(cleanup.helper_after_join, B177LatestDisposition::Gone);
        assert_eq!(cleanup.provider_after_join, B177LatestDisposition::Gone);
        assert!(
            cleanup.diagnostics.iter().any(|line| {
                line.starts_with("helper ")
                    && line.contains("termSent=false")
                    && line.contains("killSent=false")
            }),
            "cleanup={:?}",
            cleanup.diagnostics
        );
        assert!(
            cleanup.diagnostics.iter().any(|line| {
                line.starts_with("provider ")
                    && line.contains("termSent=true")
                    && line.contains("killSent=true")
            }),
            "cleanup={:?}",
            cleanup.diagnostics
        );
        let details = cleanup
            .completed
            .expect("meta cleanup lost supervisor result")
            .expect("meta supervision returned an error");
        assert!(details.residual_child.is_none());
        assert!(!details.outcome.terminal_seen);
        assert!(started.elapsed() < Duration::from_secs(10));
    }

    #[test]
    fn b177_failure_cleanup_meta_outer_bounds_no_terminal_zombie_scene() {
        let root = temp_root("failure-cleanup-meta-outer");
        fs::create_dir_all(&root).unwrap();
        let admission_path = root.join("failure-meta-admitted");
        let transfer_path = root.join("failure-meta-transferred");
        assert!(
            !admission_path.exists(),
            "failure-meta admission ACK must start absent"
        );
        assert!(
            !transfer_path.exists(),
            "failure-meta transfer marker must start absent"
        );
        let outer_deadline = Instant::now() + Duration::from_secs(20);
        let mut command = Command::new(std::env::current_exe().unwrap());
        command
            .args([
                "--exact",
                B177_FAILURE_META_INNER_TEST,
                "--nocapture",
                "--test-threads=1",
            ])
            .env(B177_FAILURE_META_ROOT_ENV, &root)
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0);
        let scenario = command.spawn().unwrap();
        let mut guard = B177FailureMetaOuterGuard::new(scenario).unwrap();
        let marker_path = root.join("failure-meta-marker.json");
        wait_for_fixture_file(
            &marker_path,
            outer_deadline
                .checked_sub(Duration::from_secs(10))
                .unwrap_or(outer_deadline),
            "failure-meta receipt sidecar",
        )
        .unwrap();
        let marker: B177FailureMetaMarker =
            serde_json::from_slice(&fs::read(&marker_path).unwrap())
                .expect("parse failure-meta receipt sidecar");
        guard.validate_and_install_marker(marker.clone()).unwrap();
        let withheld_until = Instant::now() + Duration::from_secs(1);
        while Instant::now() < withheld_until {
            assert!(
                !transfer_path.exists(),
                "inner transferred provider custody before admission ACK"
            );
            assert!(
                guard
                    .scenario
                    .as_mut()
                    .expect("failure-meta outer guard lost scenario Child")
                    .try_wait()
                    .unwrap()
                    .is_none(),
                "inner exited while admission ACK was withheld"
            );
            assert_eq!(
                inspect_stable_process(marker.provider.pid)
                    .unwrap()
                    .as_ref(),
                Some(&marker.provider),
                "provider epoch changed before admission ACK"
            );
            assert_eq!(
                inspect_stable_process(marker.helper.pid).unwrap().as_ref(),
                Some(&marker.helper),
                "helper epoch changed before admission ACK"
            );
            std::thread::sleep(Duration::from_millis(5));
        }
        atomic_publish_fixture_bytes(&admission_path, b"admitted\n").unwrap();
        assert_eq!(
            fs::read(&admission_path).unwrap(),
            b"admitted\n",
            "outer must publish one exact admission ACK"
        );
        wait_for_fixture_file(
            &transfer_path,
            outer_deadline,
            "failure-meta provider-custody transfer marker",
        )
        .unwrap();
        assert_eq!(
            fs::read(&transfer_path).unwrap(),
            b"transferred\n",
            "inner must publish one exact post-ACK transfer marker"
        );
        let status = guard.scenario_status_until(outer_deadline).unwrap();
        let Some(status) = status else {
            panic!(
                "inner scenario missed the 20s success acceptance window; fail-closed Drop retains custody"
            );
        };
        assert!(
            status.success(),
            "inner scenario failed; fail-closed Drop retains sidecar custody"
        );
        let evidence = guard.cleanup_until(outer_deadline);
        let final_gone = evidence.helper_after_scenario_reap == B177LatestDisposition::Gone
            && evidence.provider_after_scenario_reap == B177LatestDisposition::Gone
            && evidence.scenario_after_reap == B177LatestDisposition::Gone;
        if final_gone {
            guard.disarm();
        }
        assert!(
            matches!(
                evidence.helper_before_scenario_reap,
                B177LatestDisposition::Gone | B177LatestDisposition::ZombiePendingProviderReap
            ),
            "evidence={evidence:?}"
        );
        assert!(
            matches!(
                evidence.provider_before_scenario_reap,
                B177LatestDisposition::Gone | B177LatestDisposition::ZombiePendingProviderReap
            ),
            "evidence={evidence:?}"
        );
        assert!(!evidence.diagnostics.is_empty(), "evidence={evidence:?}");
        assert!(final_gone, "evidence={evidence:?}");
        assert!(Instant::now() < outer_deadline, "evidence={evidence:?}");
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_failure_meta_rejects_unrelated_victim_sidecar_without_signal() {
        let mut scenario_command = Command::new("/bin/sleep");
        scenario_command
            .arg("0.2")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0);
        let mut guard = B177FailureMetaOuterGuard::new(scenario_command.spawn().unwrap()).unwrap();

        let mut provider_command = Command::new("/bin/sleep");
        provider_command
            .arg("60")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        configure_isolated_session(&mut provider_command);
        let provider = provider_command.spawn().unwrap();
        let mut provider_guard = FixtureProcessGuard::new(provider, Vec::new());
        let provider_receipt = provider_guard
            .owned
            .get(&provider_guard.provider_pgid)
            .cloned()
            .unwrap();

        let mut helper_command = Command::new("/bin/sleep");
        helper_command
            .arg("60")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        configure_isolated_session(&mut helper_command);
        let helper = helper_command.spawn().unwrap();
        let mut helper_guard = FixtureProcessGuard::new(helper, Vec::new());
        let helper_receipt = helper_guard
            .owned
            .get(&helper_guard.provider_pgid)
            .cloned()
            .unwrap();

        let error = guard
            .validate_and_install_marker(B177FailureMetaMarker {
                provider: provider_receipt,
                helper: helper_receipt,
            })
            .unwrap_err();
        assert!(format!("{error:#}").contains("provenance"));
        assert!(guard.marker.is_none());
        assert!(
            provider_guard
                .child
                .as_mut()
                .unwrap()
                .try_wait()
                .unwrap()
                .is_none()
                && helper_guard
                    .child
                    .as_mut()
                    .unwrap()
                    .try_wait()
                    .unwrap()
                    .is_none(),
            "rejected unrelated sidecar must deliver zero signal"
        );
        assert!(process_group_alive_exact(provider_guard.provider_pgid).unwrap());
        assert!(process_group_alive_exact(helper_guard.provider_pgid).unwrap());

        let status = guard
            .scenario_status_until(Instant::now() + Duration::from_secs(2))
            .unwrap()
            .expect("short scenario did not exit naturally");
        assert!(status.success());
        assert_eq!(
            b177_fresh_epoch_retirement_until(
                std::slice::from_ref(&guard.scenario_receipt),
                Instant::now() + Duration::from_secs(1),
            ),
            B177LatestDisposition::Gone
        );
        drop(provider_guard);
        drop(helper_guard);
    }

    #[test]
    fn b177_launch_spec_rejects_alias_parents_symlink_program_and_nonexecutable() {
        let root = temp_root("launch-spec-hardening");
        let logs = root.join("coordination/runtime/logs");
        let supervisors = root.join("coordination/runtime/supervisors");
        let bin = root.join("bin");
        fs::create_dir_all(&logs).unwrap();
        fs::create_dir_all(&supervisors).unwrap();
        fs::create_dir_all(&bin).unwrap();
        let program = bin.join("opencode");
        fs::write(&program, b"#!/bin/sh\nexit 0\n").unwrap();
        fs::set_permissions(&program, fs::Permissions::from_mode(0o644)).unwrap();
        let log_path = logs.join("wake.jsonl");
        fs::write(&log_path, b"").unwrap();
        let token = "0123456789abcdef0123456789abcdef";
        let good = serde_json::json!({
            "version": 1,
            "token": token,
            "argv": [program.clone(), "run"],
            "cwd": root.clone(),
            "logPath": log_path.clone(),
            "ackPath": supervisors.join(format!("{token}.ack.json")),
            "statusPath": supervisors.join(format!("{token}.status.json")),
            "policy": {
                "naturalExitGraceMs": 3000,
                "termGraceMs": 2000,
                "pollIntervalMs": 20
            }
        });

        assert!(
            parse_wake_supervisor_launch_spec(&root, &serde_json::to_vec(&good).unwrap())
                .unwrap_err()
                .contains("executable")
        );
        fs::set_permissions(&program, fs::Permissions::from_mode(0o755)).unwrap();
        let parsed =
            parse_wake_supervisor_launch_spec(&root, &serde_json::to_vec(&good).unwrap()).unwrap();
        assert_eq!(
            PathBuf::from(&parsed.argv[0]),
            fs::canonicalize(&program).unwrap()
        );
        assert_eq!(parsed.cwd, fs::canonicalize(&root).unwrap());
        assert_eq!(parsed.log_path, fs::canonicalize(&log_path).unwrap());

        let mut stale_protocol = good.clone();
        stale_protocol["protocolRevision"] = serde_json::json!(1);
        assert!(parse_wake_supervisor_launch_spec(
            &root,
            &serde_json::to_vec(&stale_protocol).unwrap()
        )
        .unwrap_err()
        .contains("protocolRevision must be 2 (legacy) or 3"));

        let link_bin = root.join("link-bin");
        fs::create_dir_all(&link_bin).unwrap();
        let program_link = link_bin.join("opencode");
        std::os::unix::fs::symlink(&program, &program_link).unwrap();
        let mut linked_program = good.clone();
        linked_program["argv"][0] = serde_json::json!(program_link);
        assert!(parse_wake_supervisor_launch_spec(
            &root,
            &serde_json::to_vec(&linked_program).unwrap()
        )
        .is_err());

        let logs_link = root.join("logs-link");
        std::os::unix::fs::symlink(&logs, &logs_link).unwrap();
        let mut linked_log_parent = good.clone();
        linked_log_parent["logPath"] = serde_json::json!(logs_link.join("wake.jsonl"));
        assert!(parse_wake_supervisor_launch_spec(
            &root,
            &serde_json::to_vec(&linked_log_parent).unwrap()
        )
        .is_err());

        let supervisors_link = root.join("supervisors-link");
        std::os::unix::fs::symlink(&supervisors, &supervisors_link).unwrap();
        let mut linked_target_parent = good;
        linked_target_parent["ackPath"] =
            serde_json::json!(supervisors_link.join(format!("{token}.ack.json")));
        assert!(parse_wake_supervisor_launch_spec(
            &root,
            &serde_json::to_vec(&linked_target_parent).unwrap()
        )
        .is_err());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_launch_frame_read_is_bounded_before_newline() {
        const LIMIT: usize = 1024 * 1024;
        let mut oversized = std::io::Cursor::new(vec![b'x'; LIMIT + 64]);
        assert!(read_bounded_launch_frame(&mut oversized).is_err());
        assert_eq!(oversized.position(), (LIMIT + 2) as u64);

        let mut exact = vec![b'x'; LIMIT];
        exact.push(b'\n');
        let mut exact = std::io::Cursor::new(exact);
        assert_eq!(read_bounded_launch_frame(&mut exact).unwrap().len(), LIMIT);
    }

