    #[test]
    fn b177_containment_epoch_survives_full_opaque_representation_changes_without_signal_authority()
    {
        let mut full = synthetic_topology(41, 10, 41);
        full.zombie = true;
        let opaque = OpaqueZombieProof {
            pid: full.pid,
            observed_ppid: full.observed_ppid,
            pgid: full.pgid,
            uid: full.uid,
            birth_identity: Some(full.birth_identity.clone()),
        };

        let full_epoch = ZombieEpochObservation::from_topology(&full)
            .unwrap()
            .unwrap();
        let opaque_epoch = ZombieEpochObservation::from_opaque(&opaque).unwrap();
        let from_full = stable_containment_creation(&full_epoch, &opaque_epoch, 10, 7, 501)
            .expect("full->opaque same epoch must create durable custody");
        let from_opaque = stable_containment_creation(&opaque_epoch, &full_epoch, 10, 7, 501)
            .expect("opaque->full same epoch must create durable custody");
        assert_eq!(from_full.birth_identity, from_opaque.birth_identity);
        assert_eq!(from_full.sid, Some(7));
        assert_eq!(from_opaque.sid, Some(7));

        let mut wrong_sid = full.clone();
        wrong_sid.sid = 8;
        let wrong_sid = ZombieEpochObservation::from_topology(&wrong_sid)
            .unwrap()
            .unwrap();
        let cross_sid = stable_containment_creation(&opaque_epoch, &wrong_sid, 10, 7, 501)
            .expect("opaque unknown SID may bind a stable direct-child full SID");
        assert_eq!(cross_sid.sid, Some(8));
        assert!(stable_containment_creation(&full_epoch, &wrong_sid, 10, 7, 501).is_none());
        let mut wrong_birth = opaque_epoch.clone();
        wrong_birth.birth_identity = "other-birth".to_string();
        assert!(stable_containment_creation(&full_epoch, &wrong_birth, 10, 7, 501).is_none());

        let owned = BTreeMap::<u32, ManagedProcessCredential>::new();
        let containment = BTreeMap::from([(full.pid, from_full.clone())]);
        let partition = HelperGroupPartition {
            containment_zombie_awaiting_provider_reap: BTreeSet::from([full.pgid]),
            ..HelperGroupPartition::default()
        };
        assert!(owned.is_empty());
        assert_eq!(containment.len(), 1);
        assert!(partition.live.is_empty());
        assert!(partition.owned_zombie_awaiting_provider_reap.is_empty());
        assert_eq!(partition.all_zombies(), BTreeSet::from([full.pgid]));

        let mut sidless_full = full.clone();
        sidless_full.sid = 0;
        let sidless = sidless_zombie_containment_proof(&sidless_full).unwrap();
        assert_eq!(sidless.birth_identity.as_deref(), Some("birth-41"));
        let census = ProcessTopologyCensus {
            listed_pids: BTreeSet::from([full.pid]),
            topology: BTreeMap::from([(full.pid, sidless_full)]),
            opaque_zombies: BTreeMap::from([(full.pid, sidless)]),
        };
        assert_eq!(
            classify_custody_epoch(&from_full, &census).unwrap(),
            CustodyEpochState::PresentExact
        );
        assert!(owned.is_empty());
    }

