    #[test]
    fn b177_darwin_short_zombie_rejects_kernel_permission_and_abi_faults() {
        let expected = std::mem::size_of::<KinfoProcZombie>();
        let permission = classify_darwin_zombie_kernel_read(true, -1, Some(1), expected)
            .unwrap_err()
            .to_string();
        assert!(permission.contains("after exact SHORTBSDINFO zombie"));
        assert!(permission.contains("errno=Some(1)"));

        for drift in [expected - 1, expected + 1] {
            let size_error = classify_darwin_zombie_kernel_read(true, 0, None, drift)
                .unwrap_err()
                .to_string();
            assert!(size_error.contains("ABI size drift"));
            assert!(size_error.contains("after exact SHORTBSDINFO zombie"));
        }

        assert_eq!(
            classify_darwin_zombie_kernel_read(false, 0, None, 0).unwrap(),
            DarwinKernProcDisposition::Missing
        );
        assert_eq!(
            classify_darwin_zombie_kernel_read(true, 0, None, 0).unwrap(),
            DarwinKernProcDisposition::Missing
        );
        assert_eq!(
            classify_darwin_zombie_kernel_read(true, 0, None, expected).unwrap(),
            DarwinKernProcDisposition::Full
        );

        let short = DarwinShortProcessProof {
            pid: 41,
            observed_ppid: 10,
            pgid: 41,
            status: 5,
            uid: 501,
        };
        validate_darwin_short_kernel_identity(Some(&short), 41, 5, 10, 41, 501).unwrap();
        for mismatch in [
            (42, 5, 10, 41, 501),
            (41, 2, 10, 41, 501),
            (41, 5, 11, 41, 501),
            (41, 5, 10, 42, 501),
            (41, 5, 10, 41, 502),
        ] {
            assert!(validate_darwin_short_kernel_identity(
                Some(&short),
                mismatch.0,
                mismatch.1,
                mismatch.2,
                mismatch.3,
                mismatch.4,
            )
            .is_err());
        }
        validate_darwin_kernel_process_row(41, 5, 41, 10, 41, 100, 123).unwrap();
        validate_darwin_kernel_process_row(41, 2, 41, 10, 41, 100, 123).unwrap();
        assert_eq!(
            classify_darwin_kernel_process_kind(2).unwrap(),
            DarwinKernelProcessKind::Live
        );
        assert_eq!(
            classify_darwin_kernel_process_kind(5).unwrap(),
            DarwinKernelProcessKind::Zombie
        );
        assert!(classify_darwin_kernel_process_kind(0).is_err());
        assert!(classify_darwin_kernel_process_kind(6).is_err());
        assert!(validate_darwin_kernel_process_row(41, 5, 42, 10, 41, 100, 123).is_err());
    }

    #[cfg(target_os = "macos")]
    #[test]
    fn b177_darwin_libproc_decoders_reject_empty_unaligned_and_partial_envelopes() {
        let full = std::mem::size_of::<ProcBsdInfo>();
        let short = std::mem::size_of::<ProcBsdShortInfo>();
        assert_eq!(
            classify_darwin_fixed_read("full", 0, Some(3), full).unwrap(),
            DarwinFixedReadDisposition::Missing
        );
        assert_eq!(
            classify_darwin_fixed_read("short", short as i32, Some(0), short).unwrap(),
            DarwinFixedReadDisposition::Exact
        );
        for errno in [None, Some(1), Some(22)] {
            assert!(classify_darwin_fixed_read("missing", 0, errno, full).is_err());
        }
        for (written, expected) in [
            (-1, full),
            (1, full),
            (full as i32 - 1, full),
            (full as i32 + 1, full),
            (short as i32 - 1, short),
        ] {
            assert!(classify_darwin_fixed_read("fault", written, Some(5), expected).is_err());
        }
        assert!(classify_darwin_fixed_read("fault", full as i32, Some(1), full).is_err());

        validate_darwin_full_topology_row(41, 41, 2, 41, 100, 123).unwrap();
        for invalid in [
            (41, 42, 2, 41, 100, 123),
            (41, 41, 0, 41, 100, 123),
            (41, 41, 6, 41, 100, 123),
            (41, 41, 2, 0, 100, 123),
            (41, 41, 2, 41, 0, 123),
            (41, 41, 2, 41, 100, 1_000_000),
        ] {
            assert!(validate_darwin_full_topology_row(
                invalid.0, invalid.1, invalid.2, invalid.3, invalid.4, invalid.5,
            )
            .is_err());
        }
        assert_eq!(
            classify_darwin_sid_read(41, Some(0), false).unwrap(),
            Some(41)
        );
        assert!(classify_darwin_sid_read(41, Some(1), false).is_err());
        assert!(classify_darwin_sid_read(0, Some(0), false).is_err());
        assert_eq!(classify_darwin_sid_read(-1, Some(3), false).unwrap(), None);
        assert_eq!(
            classify_darwin_sid_read(-1, Some(1), true).unwrap(),
            Some(0)
        );
        for errno in [None, Some(1), Some(22)] {
            assert!(classify_darwin_sid_read(-1, errno, false).is_err());
        }

        for bytes in [-1, 0, 1, 3, 5] {
            assert!(decode_darwin_pid_list_count(bytes, Some(0), 8).is_err());
        }
        assert_eq!(decode_darwin_pid_list_count(4, Some(0), 8).unwrap(), 1);
        assert_eq!(decode_darwin_pid_list_count(32, Some(0), 8).unwrap(), 8);
        assert!(decode_darwin_pid_list_count(4, Some(1), 8).is_err());
        assert!(decode_darwin_pid_list_count(36, Some(0), 8).is_err());

        assert_eq!(decode_darwin_group_pid_count(0, Some(0), 8).unwrap(), 0);
        assert_eq!(decode_darwin_group_pid_count(8, Some(0), 8).unwrap(), 8);
        for (count, errno) in [(0, Some(1)), (1, Some(22)), (-1, Some(5)), (9, Some(0))] {
            assert!(decode_darwin_group_pid_count(count, errno, 8).is_err());
        }
        assert_eq!(
            validate_darwin_pid_rows("rows", &[3, 1, 2]).unwrap(),
            [1, 2, 3]
        );
        for rows in [vec![0, 1], vec![-1, 1], vec![1, 1]] {
            assert!(validate_darwin_pid_rows("rows", &rows).is_err());
        }
        assert_eq!(
            validate_darwin_all_pid_rows(&[3, 0, 1, 2], true).unwrap(),
            [1, 2, 3]
        );
        assert!(validate_darwin_all_pid_rows(&[1, 2, 3], true).is_err());
        assert!(validate_darwin_all_pid_rows(&[0, 1, 0], true).is_err());
        assert!(validate_darwin_all_pid_rows(&[-1, 0, 2], true).is_err());
        assert_eq!(
            validate_darwin_all_pid_rows(&[3, 1, 2], false).unwrap(),
            [1, 2, 3]
        );
        assert_eq!(checked_darwin_pid_t("pid", 41).unwrap(), 41);
        assert!(checked_darwin_pid_t("pid", 0).is_err());
        assert!(checked_darwin_pid_t("pid", u32::MAX).is_err());

        assert_eq!(
            classify_darwin_full_read(0, Some(1), full).unwrap(),
            DarwinFullReadDisposition::PermissionDenied
        );
        assert_eq!(
            classify_darwin_short_fallback_read(0, Some(1), short).unwrap(),
            DarwinFixedReadDisposition::Missing
        );
        validate_darwin_kernel_process_row(41, 2, 41, 10, 41, 100, 123).unwrap();
        assert_eq!(
            classify_darwin_sid_read(41, Some(0), false).unwrap(),
            Some(41)
        );
        assert!(classify_darwin_short_fallback_read(1, Some(0), short).is_err());

        let mut path = [0u8; 8];
        path[..3].copy_from_slice(b"abc");
        assert_eq!(
            classify_darwin_pidpath_read(3, Some(0), &path).unwrap(),
            DarwinPidPathDisposition::Exact(3)
        );
        assert_eq!(
            classify_darwin_pidpath_read(0, Some(3), &path).unwrap(),
            DarwinPidPathDisposition::Missing
        );
        assert!(classify_darwin_pidpath_read(0, Some(1), &path).is_err());
        assert!(classify_darwin_pidpath_read(3, Some(1), &path).is_err());
        assert!(classify_darwin_pidpath_read(8, Some(0), &path).is_err());
        let embedded = [b'a', 0, b'b', 0];
        assert!(classify_darwin_pidpath_read(3, Some(0), &embedded).is_err());
        let unterminated = [b'a', b'b', b'c', b'd'];
        assert!(classify_darwin_pidpath_read(3, Some(0), &unterminated).is_err());
    }

