    #[test]
    fn b241_residual_deadline_is_rechecked_before_every_signal() {
        let delay = Duration::from_millis(750);
        let signal_window = Duration::from_millis(500);

        let mut before_term = ProofCadenceGroupControl {
            proofs: VecDeque::from([Ok(GroupCredentialProof::OwnedLive)]),
            waits: VecDeque::new(),
            signals: Vec::new(),
            proof_calls: 0,
            proof_delays: VecDeque::from([delay]),
            wait_budgets: Vec::new(),
        };
        let before_term_outcome = terminate_revalidated_group_until(
            &mut before_term,
            77,
            &BTreeMap::new(),
            Duration::from_millis(30),
            Some(Instant::now() + signal_window),
        );

        let mut before_kill = ProofCadenceGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
            ]),
            waits: VecDeque::from([Ok(false)]),
            signals: Vec::new(),
            proof_calls: 0,
            proof_delays: VecDeque::from([Duration::ZERO, delay]),
            wait_budgets: Vec::new(),
        };
        let before_kill_outcome = terminate_revalidated_group_until(
            &mut before_kill,
            77,
            &BTreeMap::new(),
            Duration::from_millis(30),
            Some(Instant::now() + signal_window),
        );

        let mut before_repeat = ProofCadenceGroupControl {
            proofs: VecDeque::from([
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
                Ok(GroupCredentialProof::OwnedLive),
            ]),
            waits: VecDeque::from([Ok(false), Ok(false)]),
            signals: Vec::new(),
            proof_calls: 0,
            proof_delays: VecDeque::from([Duration::ZERO, Duration::ZERO, delay]),
            wait_budgets: Vec::new(),
        };
        let before_repeat_outcome = terminate_revalidated_group_until(
            &mut before_repeat,
            77,
            &BTreeMap::new(),
            Duration::from_millis(30),
            Some(Instant::now() + signal_window),
        );

        assert!(before_term_outcome.convergence_budget_exhausted);
        assert!(before_term.signals.is_empty());
        assert!(before_kill_outcome.convergence_budget_exhausted);
        assert_eq!(before_kill.signals, [crate::tierf::TerminationSignal::Term]);
        assert!(before_repeat_outcome.convergence_budget_exhausted);
        assert_eq!(
            before_repeat.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill
            ]
        );
    }

    #[test]
    fn b241_residual_convergence_gives_up_without_any_signal() {
        let provider = Command::new("/bin/sleep")
            .arg("60")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0)
            .spawn()
            .unwrap();
        let provider_pid = provider.id();
        let mut helper = Command::new("/bin/sleep")
            .arg("60")
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(provider_pid as i32)
            .spawn()
            .unwrap();
        let helper_pid = helper.id();
        let provider_credential = inspect_stable_process(provider_pid).unwrap().unwrap();
        let mut owner = ManagedTreeOwner::new(
            provider,
            Vec::new(),
            Some(provider_credential),
            false,
            ProcessObserver::default(),
        );
        owner.residual_convergence_budget_override = Some(Duration::from_millis(300));
        let started = Instant::now();
        let result = owner.converge_residual_tree();
        let elapsed = started.elapsed();
        let (evidence, message, gave_up) = match result {
            Ok(evidence) => (evidence, String::new(), false),
            Err(failure) => {
                let message = failure.message();
                (failure.evidence, message, true)
            }
        };
        let provider_survived_giveup = owner.child.as_mut().unwrap().try_wait().unwrap().is_none();
        let helper_survived_giveup = helper.try_wait().unwrap().is_none();
        let second_started = Instant::now();
        let second_call_refused = owner.converge_residual_tree().is_err();
        let second_elapsed = second_started.elapsed();

        // Manual recovery happens only after all no-signal evidence has been
        // captured. Each positive PID is backed by its exact Child handle.
        let _ = helper.kill();
        helper.wait().unwrap();
        let provider_status = {
            let child = owner.child.as_mut().unwrap();
            if let Some(status) = child.try_wait().unwrap() {
                status
            } else {
                let _ = child.kill();
                child.wait().unwrap()
            }
        };
        owner.child_status = Some(provider_status);
        owner.release_reaped_child();
        drop(owner);

        assert!(gave_up, "an unprovable group must return a give-up error");
        assert!(elapsed < Duration::from_secs(3), "elapsed={elapsed:?}");
        assert!(message.contains(&provider_pid.to_string()), "{message}");
        assert!(message.contains(&helper_pid.to_string()), "{message}");
        assert!(evidence.signals.is_empty());
        assert!(evidence.signal_trace.is_empty());
        assert!(provider_survived_giveup);
        assert!(helper_survived_giveup);
        assert!(second_call_refused);
        assert!(
            second_elapsed < Duration::from_millis(150),
            "latched give-up restarted convergence: {second_elapsed:?}"
        );
    }

