    #[test]
    fn b177_cross_pgid_sticky_zombie_waits_for_provider_reap_then_converges() {
        let root = temp_root("cross-pgid-sticky-zombie");
        fs::create_dir_all(&root).unwrap();
        let fixture_deadline = Instant::now() + Duration::from_secs(12);
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let ready = root.join("ready");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command =
            b177_fixture_command(&root, "provider-cross-pgid-sticky-zombie", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(
            child,
            vec![ready.join("zombie-pid"), ready.join("helper-ready")],
        );
        let provider_pgid = fixture.provider_pgid;
        let provider = inspect_stable_process(provider_pgid)
            .unwrap()
            .expect("cross-PGID provider lacks a stable credential");
        let promoted = std::sync::Arc::new((
            std::sync::Mutex::new(BTreeSet::<u32>::new()),
            std::sync::Condvar::new(),
        ));
        let (done_tx, done_rx) = std::sync::mpsc::sync_channel(1);
        let supervised_provider = provider.clone();
        let supervisor_policy = WakeSupervisorPolicy {
            natural_exit_grace_ms: 50,
            term_grace_ms: 30,
            poll_interval_ms: 5,
        };
        let mut supervisor = Some(std::thread::spawn({
            let log_path = log_path.clone();
            let promoted = std::sync::Arc::clone(&promoted);
            let child = fixture.take_child();
            move || {
                let result = supervise_managed_child_with_baseline(
                    child,
                    "opencode",
                    &log_path,
                    supervisor_policy,
                    baseline,
                    Some(supervised_provider),
                    None,
                    true,
                    ProcessObserver {
                        owned_promotion_notify: Some(promoted),
                        ..ProcessObserver::default()
                    },
                );
                let _ = done_tx.send(result);
            }
        }));
        let helper_ready = ready.join("helper-ready");
        let mut helper_pid = None;
        let mut helper_receipt = None;
        let protocol = (|| -> Result<OpaqueZombieProof> {
            wait_for_fixture_file(
                &helper_ready,
                fixture_deadline,
                "cross-PGID helper readiness",
            )?;
            let exact_helper_pid = fs::read_to_string(&helper_ready)
                .context("read cross-PGID helper readiness")?
                .trim()
                .parse::<u32>()
                .context("parse cross-PGID helper pid")?;
            helper_pid = Some(exact_helper_pid);

            let (lock, condition) = &*promoted;
            let promoted_pids = lock
                .lock()
                .map_err(|_| anyhow::anyhow!("owned-promotion mutex poisoned"))?;
            let (promoted_pids, _) = condition
                .wait_timeout_while(
                    promoted_pids,
                    remaining_test_deadline(fixture_deadline, "cross-PGID promotion")?,
                    |pids| !pids.contains(&exact_helper_pid),
                )
                .map_err(|_| anyhow::anyhow!("owned-promotion condvar poisoned"))?;
            if !promoted_pids.contains(&exact_helper_pid) {
                bail!("exact cross-PGID helper never received an owned receipt");
            }
            drop(promoted_pids);

            let receipt = inspect_stable_process(exact_helper_pid)?
                .context("promoted cross-PGID helper lost its stable credential")?;
            if receipt.pid != exact_helper_pid
                || receipt.observed_ppid != provider_pgid
                || receipt.pgid != exact_helper_pid
            {
                bail!(
                    "cross-PGID helper credential has wrong pid/ppid/pgid: {}/{}/{}",
                    receipt.pid,
                    receipt.observed_ppid,
                    receipt.pgid
                );
            }
            helper_receipt = Some(receipt.clone());
            fs::write(ready.join("release-helper"), b"release\n")?;

            let zombie = loop {
                match inspect_opaque_zombie(exact_helper_pid) {
                    Ok(Some(zombie)) => {
                        if !owned_zombie_epoch_matches_receipt(&receipt, &zombie)
                            || zombie.observed_ppid != provider_pgid
                            || zombie.pgid != exact_helper_pid
                        {
                            bail!("cross-PGID helper zombie proof changed birth/uid/ppid/pgid");
                        }
                        break zombie;
                    }
                    Ok(None) => {}
                    Err(error) if error.to_string().contains("proved a live process") => {}
                    Err(error) => return Err(error.context("inspect cross-PGID helper zombie")),
                }
                remaining_test_deadline(fixture_deadline, "cross-PGID strong zombie proof")?;
                std::thread::sleep(Duration::from_millis(5));
            };
            fs::write(ready.join("emit-terminal-now"), b"terminal\n")?;
            Ok(zombie)
        })();

        let mut completed = None;
        let mut failure = protocol.as_ref().err().map(|error| format!("{error:#}"));
        if failure.is_none() {
            match done_rx.recv_timeout(
                remaining_test_deadline(fixture_deadline, "cross-PGID supervision")
                    .unwrap_or(Duration::ZERO),
            ) {
                Ok(result) => completed = Some(result),
                Err(error) => failure = Some(format!("cross-PGID supervision timed out: {error}")),
            }
        }

        if let Some(failure) = failure {
            let cleanup = b177_bounded_fixture_failure_cleanup(
                "cross-PGID",
                &[
                    ready.join("release-helper"),
                    ready.join("emit-terminal-now"),
                ],
                Some(&helper_ready),
                &mut helper_receipt,
                &provider,
                supervisor_policy,
                &done_rx,
                &mut supervisor,
            );
            completed = cleanup.completed;
            panic!(
                "cross-PGID bounded fixture failed: {failure}; joined={}; cleanup={:?}; before={:?}/{:?}; after={:?}/{:?}; completed={}",
                cleanup.joined,
                cleanup.diagnostics,
                cleanup.helper_before_join,
                cleanup.provider_before_join,
                cleanup.helper_after_join,
                cleanup.provider_after_join,
                completed.is_some()
            );
        }

        let zombie = protocol.unwrap();
        let helper_pgid = helper_pid.expect("protocol recorded helper pid");
        assert_eq!(
            zombie.birth_identity.as_deref(),
            helper_receipt
                .as_ref()
                .map(|receipt| receipt.birth_identity.as_str())
        );
        let mut details = completed
            .expect("completed result recorded")
            .expect("cross-PGID supervision returned an error");
        supervisor
            .take()
            .unwrap()
            .join()
            .expect("supervision thread panicked");
        if details.residual_child.is_some()
            || details.error.is_some()
            || !details.ambiguity.is_empty()
            || !details.outcome.process_tree_terminated
        {
            converge_supervision_residual(&mut details);
            panic!(
                "cross-PGID supervision was not clean: error={:?} ambiguity={:?} order={:?}",
                details.error, details.ambiguity, details.termination_order
            );
        }
        assert!(details.owned_helpers >= 1);
        assert_eq!(details.termination_order.first(), Some(&helper_pgid));
        assert_eq!(details.termination_order.last(), Some(&provider_pgid));
        assert!(details.error.is_none());
        assert!(details.ambiguity.is_empty());
        assert!(details.residual_child.is_none());
        assert_eq!(
            details.signal_trace,
            [
                (provider_pgid, crate::tierf::TerminationSignal::Term),
                (provider_pgid, crate::tierf::TerminationSignal::Kill),
            ]
        );
        assert!(!process_group_alive_exact(helper_pgid).unwrap());
        assert!(!process_group_alive_exact(provider_pgid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_post_warmup_opaque_zombie_is_containment_only_and_never_signalled() {
        let root = temp_root("post-warmup-opaque-containment");
        fs::create_dir_all(&root).unwrap();
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let ready = root.join("ready");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command =
            b177_fixture_command(&root, "provider-delayed-same-sid-zombie", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, vec![ready.join("zombie-pid")]);
        let provider_pgid = fixture.provider_pgid;
        let deadline = Instant::now() + Duration::from_secs(5);
        while !ready.join("provider-ready").is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(ready.join("provider-ready").is_file());
        let provider = inspect_stable_process(provider_pgid)
            .unwrap()
            .expect("fixture provider must have a full receipt");
        assert_eq!(provider.sid, provider_pgid);

        let completed =
            std::sync::Arc::new((std::sync::Mutex::new(0usize), std::sync::Condvar::new()));
        let force_opaque = std::sync::Arc::new(std::sync::atomic::AtomicU32::new(0));
        let supervisor = std::thread::spawn({
            let log_path = log_path.clone();
            let completed = std::sync::Arc::clone(&completed);
            let force_opaque = std::sync::Arc::clone(&force_opaque);
            let child = fixture.take_child();
            move || {
                supervise_managed_child_with_baseline(
                    child,
                    "opencode",
                    &log_path,
                    WakeSupervisorPolicy {
                        natural_exit_grace_ms: 50,
                        term_grace_ms: 30,
                        poll_interval_ms: 5,
                    },
                    baseline,
                    Some(provider),
                    None,
                    true,
                    ProcessObserver {
                        scheduled_observation_notify: Some(completed),
                        force_opaque_pid: Some(force_opaque),
                        ..ProcessObserver::default()
                    },
                )
            }
        });

        let (lock, condition) = &*completed;
        let observed = lock.lock().unwrap();
        let (observed, wait) = condition
            .wait_timeout_while(observed, Duration::from_secs(5), |count| *count < 4)
            .unwrap();
        assert!(
            !wait.timed_out(),
            "startup observation burst did not complete"
        );
        assert_eq!(*observed, 4);
        drop(observed);
        fs::write(ready.join("create-helper-now"), b"create\n").unwrap();

        let zombie_pid_path = ready.join("zombie-pid");
        let deadline = Instant::now() + Duration::from_secs(5);
        while !zombie_pid_path.is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let helper_pgid = fs::read_to_string(&zombie_pid_path)
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        assert_ne!(helper_pgid, provider_pgid);
        let deadline = Instant::now() + Duration::from_secs(5);
        let zombie = loop {
            if let Some(zombie) = inspect_opaque_zombie(helper_pgid).unwrap() {
                if zombie.birth_identity.is_some() {
                    break zombie;
                }
            }
            assert!(Instant::now() < deadline, "helper did not become a zombie");
            std::thread::sleep(Duration::from_millis(5));
        };
        assert_eq!(zombie.observed_ppid, provider_pgid);
        assert_eq!(zombie.pgid, helper_pgid);

        #[cfg(target_os = "macos")]
        {
            // Prove the production Darwin census takes its natural opaque
            // fallback before test injection makes subsequent A/B timing
            // deterministic. A full BSD row must genuinely be absent.
            let deadline = Instant::now() + Duration::from_secs(5);
            loop {
                let topology_absent = inspect_topology(helper_pgid).unwrap().is_none();
                let natural_census = process_topology_census().unwrap();
                let census_is_opaque = !natural_census.topology.contains_key(&helper_pgid)
                    && natural_census
                        .opaque_zombies
                        .get(&helper_pgid)
                        .is_some_and(|proof| proof.birth_identity.is_some());
                if topology_absent && census_is_opaque {
                    break;
                }
                assert!(
                    Instant::now() < deadline,
                    "Darwin zombie never entered the natural opaque census path"
                );
                std::thread::sleep(Duration::from_millis(5));
            }
            assert!(inspect_topology(helper_pgid).unwrap().is_none());
            let natural_census = process_topology_census().unwrap();
            assert!(!natural_census.topology.contains_key(&helper_pgid));
            assert!(natural_census
                .opaque_zombies
                .get(&helper_pgid)
                .is_some_and(|proof| proof.birth_identity.is_some()));
        }

        force_opaque.store(helper_pgid, std::sync::atomic::Ordering::SeqCst);
        let mut opaque_probe = ProcessObserver {
            force_opaque_pid: Some(std::sync::Arc::clone(&force_opaque)),
            ..ProcessObserver::default()
        };
        let opaque_census = opaque_probe.topology_census().unwrap();
        assert!(!opaque_census.topology.contains_key(&helper_pgid));
        assert!(opaque_census
            .opaque_zombies
            .get(&helper_pgid)
            .is_some_and(|proof| proof.birth_identity.is_some()));
        fs::write(ready.join("emit-terminal-now"), b"terminal\n").unwrap();

        let details = supervisor
            .join()
            .expect("supervision thread panicked")
            .unwrap();
        assert!(
            details.error.is_none(),
            "unexpected error: {:?}",
            details.error
        );
        assert!(
            details.ambiguity.is_empty(),
            "unexpected ambiguity: {:?}",
            details.ambiguity
        );
        assert_eq!(details.scheduled_topology_observations, 4);
        assert_eq!(details.owned_helpers, 0);
        assert_eq!(details.containment_receipts_observed, 1);
        assert_eq!(details.pending_containment_groups_observed, 1);
        assert!(details.outcome.terminal_seen);
        assert!(
            details.outcome.process_tree_terminated,
            "error={:?} ambiguity={:?} order={:?}",
            details.error, details.ambiguity, details.termination_order
        );
        assert_eq!(details.termination_order, [provider_pgid]);
        assert!(details
            .outcome
            .signals
            .contains(&crate::tierf::TerminationSignal::Kill));
        assert!(!process_group_alive_exact(provider_pgid).unwrap());
        assert!(!process_group_alive_exact(helper_pgid).unwrap());
        assert!(details.residual_child.is_none());
        drop(fixture);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_fresh_isolated_sid_unobserved_zombie_does_not_block_provider_cleanup() {
        let root = temp_root("fresh-sid-unobserved-zombie");
        fs::create_dir_all(&root).unwrap();
        let ready = root.join("ready");
        let mut command = b177_fixture_command(&root, "provider-owned-sticky-zombie", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let provider_pgid = child.id();
        let mut owner =
            ManagedTreeOwner::new(child, Vec::new(), None, true, ProcessObserver::default());
        let deadline = Instant::now() + Duration::from_secs(5);
        while !ready.join("zombie-pid").is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let zombie_pid = fs::read_to_string(ready.join("zombie-pid"))
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        assert!(exact_group_member_pids(provider_pgid)
            .unwrap()
            .contains(&zombie_pid));
        owner.ensure_provider_owned().unwrap();
        assert_eq!(owner.owned.get(&provider_pgid).unwrap().sid, provider_pgid);
        let termination = {
            let owned = &owner.owned;
            let mut control = SystemGroupControl {
                observer: &mut owner.observer,
                direct_child: owner
                    .child
                    .as_mut()
                    .map(|child| (child, &mut owner.child_status)),
            };
            terminate_revalidated_group(
                &mut control,
                provider_pgid,
                owned,
                Duration::from_millis(30),
            )
        };
        assert!(termination.errors.is_empty(), "{:?}", termination.errors);
        assert!(termination.terminated || termination.zombie_awaiting_provider_reap);
        assert_ne!(
            termination.terminated, termination.zombie_awaiting_provider_reap,
            "direct typed reap and deferred provider reap are mutually exclusive"
        );
        assert!(termination
            .signals
            .contains(&crate::tierf::TerminationSignal::Kill));
        owner.poll_child().unwrap();
        let deadline = Instant::now() + Duration::from_secs(2);
        while process_group_alive_exact(provider_pgid).unwrap() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(owner.child_status.is_some());
        assert!(!process_group_alive_exact(provider_pgid).unwrap());
        drop(owner);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_unowned_sticky_zombie_is_rejected_without_a_group_signal() {
        let root = temp_root("unowned-sticky-zombie");
        fs::create_dir_all(&root).unwrap();
        let ready = root.join("ready");
        let mut command =
            b177_fixture_command(&root, "provider-unowned-sticky-zombie", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null())
            .process_group(0);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, Vec::new());
        let provider_pgid = fixture.provider_pgid;
        let provider = inspect_stable_process(provider_pgid)
            .unwrap()
            .expect("unowned-zombie provider lacks a stable credential");
        fixture.register_provider_receipt(provider.clone()).unwrap();
        let deadline = Instant::now() + Duration::from_secs(5);
        while !ready.join("zombie-pid").is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        let zombie_pid = fs::read_to_string(ready.join("zombie-pid"))
            .unwrap()
            .trim()
            .parse::<u32>()
            .unwrap();
        assert!(exact_group_member_pids(zombie_pid)
            .unwrap()
            .contains(&zombie_pid));
        let refusal = revalidate_group_credentials(
            &mut ProcessObserver::default(),
            zombie_pid,
            &BTreeMap::new(),
        )
        .unwrap_err();
        assert!(!refusal.is_empty(), "{refusal:?}");
        assert!(process_group_alive_exact(provider_pgid).unwrap());
        let watchdog = run_exact_group_watchdog(
            provider_pgid,
            &BTreeMap::from([(provider.pid, provider)]),
            Instant::now() + Duration::from_secs(3),
        )
        .unwrap();
        assert!(watchdog.term_sent || watchdog.kill_sent || watchdog.esrch);
        assert!(fixture.wait_until_exited(Duration::from_secs(2)));
        assert!(!process_group_alive_exact(provider_pgid).unwrap());
        assert!(!process_group_alive_exact(zombie_pid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

