    #[test]
    fn b177_residual_drop_converges_isolated_helpers_before_provider() {
        let root = temp_root("residual-drop-whole-tree");
        fs::create_dir_all(&root).unwrap();
        let ready = root.join("ready");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command = b177_fixture_command(&root, "provider-two-groups", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::null())
            .stderr(Stdio::null());
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let provider_pgid = child.id();
        // Install the production owner before the first fallible observation:
        // every panic below therefore exercises the same tree-wide Drop path.
        let owner = ManagedTreeOwner::new(child, baseline, None, true, ProcessObserver::default());
        let helper_files = [ready.join("helper-1"), ready.join("helper-2")];
        let deadline = Instant::now() + Duration::from_secs(5);
        while !helper_files.iter().all(|path| path.is_file()) && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(helper_files.iter().all(|path| path.is_file()));
        let helper_pgids = helper_files
            .iter()
            .map(|path| {
                let pid = fs::read_to_string(path)
                    .unwrap()
                    .trim()
                    .parse::<u32>()
                    .unwrap();
                inspect_stable_process(pid).unwrap().unwrap().pgid
            })
            .collect::<Vec<_>>();
        assert!(helper_pgids.iter().all(|pgid| *pgid != provider_pgid));

        let live_epoch_probe_started = Instant::now();
        assert!(
            capture_isolated_zombie_provider_epoch(provider_pgid)
                .unwrap()
                .is_none(),
            "a live Darwin provider fallback must continue to full credential settle, not become a zombie epoch"
        );
        assert!(
            live_epoch_probe_started.elapsed() < Duration::from_secs(1),
            "live provider zombie-epoch classification must not stall residual Drop"
        );

        let drop_started = Instant::now();
        drop(owner);
        assert!(
            drop_started.elapsed() < Duration::from_secs(10),
            "residual Drop must converge after LiveUnknown continues to full credential settle"
        );

        assert!(!process_group_alive_exact(provider_pgid).unwrap());
        assert!(helper_pgids
            .iter()
            .all(|pgid| !process_group_alive_exact(*pgid).unwrap()));
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b177_isolated_census_fault_refuses_provider_signal_and_success() {
        let root = temp_root("isolated-census-fail-closed");
        fs::create_dir_all(&root).unwrap();
        let log_path = root.join("wake.jsonl");
        let stdout = File::create(&log_path).unwrap();
        let stderr = stdout.try_clone().unwrap();
        let ready = root.join("provider-ready");
        let baseline = process_topology_snapshot()
            .unwrap()
            .into_values()
            .collect::<Vec<_>>();
        let mut command = b177_fixture_command(&root, "provider-stubborn", Some(&ready));
        command
            .stdin(Stdio::null())
            .stdout(Stdio::from(stdout))
            .stderr(Stdio::from(stderr));
        configure_isolated_session(&mut command);
        let child = command.spawn().unwrap();
        let mut fixture = FixtureProcessGuard::new(child, Vec::new());
        let provider_pgid = fixture.provider_pgid;
        let deadline = Instant::now() + Duration::from_secs(5);
        while !ready.is_file() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(5));
        }
        assert!(ready.is_file());
        let provider = inspect_stable_process(provider_pgid).unwrap();
        // Calls 1-14 cover the 250ms loop, terminal edge, final observation,
        // helper convergence, and the post-helper partition. The fifteenth is
        // the fresh isolated-session fence immediately before the provider
        // group would otherwise be signalled.
        let mut details = supervise_managed_child_with_baseline(
            fixture.take_child(),
            "opencode",
            &log_path,
            WakeSupervisorPolicy {
                natural_exit_grace_ms: 0,
                term_grace_ms: 30,
                poll_interval_ms: 5,
            },
            baseline,
            provider,
            None,
            true,
            ProcessObserver {
                fail_topology_at: Some(15),
                ..ProcessObserver::default()
            },
        )
        .unwrap();
        assert!(details.outcome.signals.is_empty());
        assert!(!details.outcome.process_tree_terminated);
        assert!(
            details
                .error
                .as_deref()
                .is_some_and(|error| error.contains("pre-provider isolated-session census failed")),
            "error={:?} ambiguity={:?}",
            details.error,
            details.ambiguity
        );

        // The one-shot observer fault is consumed. Explicit residual
        // convergence must return the actions/final exit/metrics that the
        // hidden status writer publishes; Drop is only the last-resort guard.
        let snapshots_before_residual = details.topology_snapshots;
        converge_supervision_residual(&mut details);
        assert!(details.outcome.process_tree_terminated);
        assert_eq!(
            details.outcome.signals,
            [
                crate::tierf::TerminationSignal::Term,
                crate::tierf::TerminationSignal::Kill
            ]
        );
        assert_eq!(details.termination_order.last(), Some(&provider_pgid));
        assert_eq!(details.exit_status, Some(-9));
        assert!(details.topology_snapshots > snapshots_before_residual);
        assert!(details.residual_child.is_none());
        assert!(details
            .error
            .as_deref()
            .is_some_and(|error| error.contains("pre-provider isolated-session census failed")));
        assert!(details
            .ambiguity
            .iter()
            .any(|item| item.contains("signal refused because helper census failed")));
        drop(details);
        assert!(!process_group_alive_exact(provider_pgid).unwrap());
        fs::remove_dir_all(root).unwrap();
    }

