    #[test]
    fn b204_late_state_machine_rejects_drift_and_recovers_only_exact_latest_orphan() {
        let root = b180_reconcile_root("b204-late-drift");
        let task = "B204";
        let attempt = "B204-A0001";
        let role = "primary";
        let agent = "executor-claw";
        let canonical = b180_review_bytes(task, attempt, role, agent, "canonical review");
        b204_append_verdict_fixture(&root, task, attempt, role, agent, &canonical, false);
        b204_stage_review(
            &root,
            task,
            attempt,
            role,
            agent,
            "first durable late revision",
        );
        let first = deliver_review(&root, task, attempt, role, agent).unwrap();
        let before = read_round_ledger_events(&root, B180_ROUND).unwrap().len();
        fs::write(
            root.join(&first.path),
            b180_review_bytes(task, attempt, role, agent, "tampered late revision"),
        )
        .unwrap();
        let error = deliver_review(&root, task, attempt, role, agent).unwrap_err();
        assert!(format!("{error:#}").contains("drifted"));
        let events = read_round_ledger_events(&root, B180_ROUND).unwrap();
        assert_eq!(events.len(), before);
        assert!(validate_late_review_deliveries(&root, B180_ROUND, &events).is_err());
        fs::remove_dir_all(root).unwrap();

        let root = b180_reconcile_root("b204-latest-orphan-recovery");
        let canonical = b180_review_bytes(task, attempt, role, agent, "canonical review");
        b204_append_verdict_fixture(&root, task, attempt, role, agent, &canonical, false);
        let staged = b204_stage_review(
            &root,
            task,
            attempt,
            role,
            agent,
            "crash-left exact orphan revision",
        );
        let orphan_rel = format!(
            "{}-late-1.md",
            b180_review_rel(attempt, role, agent).trim_end_matches(".md")
        );
        fs::write(root.join(&orphan_rel), &staged).unwrap();
        let recovered = deliver_review(&root, task, attempt, role, agent).unwrap();
        assert_eq!(recovered.path, orphan_rel);
        assert_eq!(recovered.appended_events, 2);
        let replay = deliver_review(&root, task, attempt, role, agent).unwrap();
        assert_eq!(replay.appended_events, 0);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn b204_concurrent_review_inbox_parent_creation_revalidates_the_winner() {
        let root = temp_root("b204-review-inbox-mkdir-race");
        fs::create_dir_all(&root).unwrap();
        let rel =
            review_inbox_relpath(B180_ROUND, "B204-A0001", "primary", "executor-claw").unwrap();
        let root = std::sync::Arc::new(root);
        let threads = (0..12)
            .map(|_| {
                let root = std::sync::Arc::clone(&root);
                let rel = rel.clone();
                std::thread::spawn(move || ensure_review_inbox_parent(&root, &rel))
            })
            .collect::<Vec<_>>();
        for thread in threads {
            thread.join().unwrap().unwrap();
        }
        let parent = root.join(rel).parent().unwrap().to_path_buf();
        let metadata = fs::symlink_metadata(parent).unwrap();
        assert!(metadata.is_dir());
        assert!(!metadata.file_type().is_symlink());
        fs::remove_dir_all(root.as_ref()).unwrap();
    }

    #[test]
    fn b204_formal_status_binding_is_filesystem_read_only() {
        let root = temp_root("b204-formal-binding-read-only");
        fs::create_dir_all(&root).unwrap();
        let wake_id = "wake-b204-read-only";
        let mut request = b180_review_request("B204", "B204-A0001", "primary", "executor-claw");
        let payload = request.payload.as_mut().unwrap();
        payload["wakeId"] = serde_json::json!(wake_id);
        payload["continuationId"] =
            serde_json::json!("review:r180:B204:B204-A0001:primary:executor-claw");
        let wake = ledger::event(
            "WakeIssued",
            "runtime:orch",
            Some("B204"),
            Some(B180_ROUND),
            serde_json::json!({
                "wakeId": wake_id,
                "providerKind": "opencode",
                "agent": "executor-claw",
            }),
        );
        let events = vec![b180_collect("B204", "B204-A0001"), request, wake];
        let rel =
            review_inbox_relpath(B180_ROUND, "B204-A0001", "primary", "executor-claw").unwrap();
        let parent = root.join(&rel).parent().unwrap().to_path_buf();
        assert!(!parent.exists());

        let binding = formal_review_binding_for_wake(&root, &events, B180_ROUND, wake_id).unwrap();
        assert_eq!(binding.review_path, root.join(rel).display().to_string());
        assert!(
            !parent.exists(),
            "read-only formal status projection created an inbox directory"
        );
        fs::remove_dir_all(root).unwrap();
    }

