    #[test]
    fn real_wake_entry_spawns_and_immediately_projects_pending_review() {
        let root = review_wake_root("review-real-entry");
        run_wake_with_message_authorized_review(
            &root,
            "executor-claw",
            test_review_message(),
            test_review_request(),
        )
        .unwrap();

        let ledger_text =
            fs::read_to_string(root.join("coordination/rounds/r53/events.jsonl")).unwrap();
        let ledger =
            orch_core::read_ledger(&root.join("coordination/rounds/r53/events.jsonl")).unwrap();
        assert!(ledger.bad_lines.is_empty());
        assert_eq!(
            ledger
                .events
                .iter()
                .filter(|event| event.kind == "WakeIssued")
                .count(),
            1
        );
        let requested = ledger
            .events
            .iter()
            .find(|event| event.kind == "ReviewRequested")
            .unwrap();
        let fixed_head = crate::gitx::rev_parse(&root, "refs/heads/task/B900").unwrap();
        assert_eq!(
            requested
                .payload
                .as_ref()
                .and_then(|payload| payload.get("reviewedHead"))
                .and_then(serde_json::Value::as_str),
            Some(fixed_head.as_str())
        );
        assert_eq!(
            ledger
                .events
                .iter()
                .filter(|event| event.kind == "ReviewRequested")
                .count(),
            1
        );
        // No daemon/monitor tick occurs between the real spawn and this pure
        // ledger query.
        let pending = crate::serve::pending_review_expectations(&ledger_text, "r53", 0).unwrap();
        assert_eq!(pending.len(), 1);
        assert_eq!(pending[0].task_id, "B900");
        assert_eq!(pending[0].attempt_id, "B900-A0001");
        assert_eq!(pending[0].role, "primary");
        assert_eq!(pending[0].agent, "executor-claw");

        let plan = review_site_plan_generation(
            root.to_str().unwrap(),
            "B900-A0001",
            crate::sites::SiteRole::Primary,
            "executor-claw",
            1,
        )
        .unwrap();
        let worktree = PathBuf::from(&plan.worktree);
        assert!(worktree.is_dir());
        assert!(Path::new(&plan.target_dir).is_dir());
        assert_eq!(
            crate::gitx::rev_parse(&worktree, "HEAD").unwrap(),
            crate::gitx::rev_parse(&root, "refs/heads/task/B900").unwrap()
        );
        assert!(review_worktree_is_detached(&worktree).unwrap());

        let wake = ledger
            .events
            .iter()
            .find(|event| event.kind == "WakeIssued")
            .unwrap();
        let log_path = wake
            .payload
            .as_ref()
            .and_then(|payload| payload.get("logPath"))
            .and_then(serde_json::Value::as_str)
            .unwrap();
        let injected = fs::read_to_string(log_path).unwrap();
        assert!(injected.contains(&plan.worktree));
        assert!(injected.contains(&plan.target_dir));
        for field in [
            "taskId",
            "round",
            "attemptId",
            "role",
            "reviewer",
            "verdict",
            "reviewedHead",
        ] {
            assert!(
                injected.contains(field),
                "missing review schema field {field}"
            );
        }
        assert!(injected.contains("Extra fields are ignored but reported loudly"));
        assert!(
            injected.rfind("round: r53").unwrap() > injected.rfind("round: r58").unwrap(),
            "runtime identity must follow stale planner prose"
        );
        assert!(
            injected.rfind(&fixed_head).unwrap()
                > injected
                    .rfind("2222222222222222222222222222222222222222")
                    .unwrap(),
            "runtime reviewedHead must follow stale planner prose"
        );
        assert!(injected.contains("do not commit it in the worktree"));
        assert!(injected.contains(&format!(
            "{}/coordination/runtime/review-inbox/r53/B900-A0001-primary-executor-claw.md",
            root.display()
        )));
        assert!(!injected.contains(&format!(
            "{}/coordination/rounds/r53/reviews/B900-A0001-primary-executor-claw.md",
            root.display()
        )));
        assert!(injected.contains(r#"{"type":"text","text":"OR"}"#));
        assert!(injected.contains(r#"{"type":"text","text":"CH_REVIEW_SITE_PROBE_OK="#));
        assert!(injected.contains(r#"{"type":"tool_result","output":"#));
        assert!(!ledger
            .events
            .iter()
            .any(|event| event.kind == "EscalationRaised"));

        let events = read_round_ledger_events(&root, "r53").unwrap();
        let expectation = new_review_expectation(
            &root,
            "r53",
            &events,
            &test_review_request(),
            None,
            None,
        )
        .unwrap();
        let lease_wake_id = events
            .iter()
            .find(|event| event.kind == "WorkspaceLeased")
            .and_then(|event| payload_string(event, "wakeId"))
            .unwrap();
        let reused = provision_review_site(
            &root,
            "r53",
            lease_wake_id,
            &test_review_request(),
            &expectation,
        )
        .unwrap();
        assert_eq!(reused.site, plan);
        assert_eq!(
            reused.reviewed_head,
            crate::gitx::rev_parse(&root, "refs/heads/task/B900").unwrap()
        );
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn real_nongate_wake_is_authorized_leased_isolated_retired_and_reaped() {
        let root = review_wake_root("review-real-nongate-lifecycle");
        let request = ReviewRequest {
            task_id: "B903".to_string(),
            attempt_id: "B903-A0001".to_string(),
            role: "nongate".to_string(),
            agent: "executor-pi".to_string(),
            deadline_secs: 900,
        };

        run_wake_with_message_authorized_review(
            &root,
            "executor-pi",
            test_review_message(),
            request,
        )
        .unwrap();

        let ledger_path = root.join("coordination/rounds/r53/events.jsonl");
        let after_wake = orch_core::read_ledger(&ledger_path).unwrap();
        assert!(after_wake.bad_lines.is_empty());
        let lease = after_wake
            .events
            .iter()
            .find(|event| {
                event.kind == "WorkspaceLeased"
                    && event.task_id.as_deref() == Some("B903")
                    && payload_string(event, "role") == Some("nongate")
                    && payload_string(event, "agent") == Some("executor-pi")
            })
            .expect("real nongate wake must lease its review site");
        let site_id = payload_string(lease, "siteId").unwrap().to_string();
        assert!(after_wake.events.iter().any(|event| {
            event.kind == "WakeIssued"
                && event.task_id.as_deref() == Some("B903")
                && payload_string(event, "agent") == Some("executor-pi")
        }));
        assert!(!after_wake.events.iter().any(|event| {
            event.kind == "ReviewRequested" && event.task_id.as_deref() == Some("B903")
        }));

        let wake = after_wake
            .events
            .iter()
            .find(|event| {
                event.kind == "WakeIssued"
                    && event.task_id.as_deref() == Some("B903")
                    && payload_string(event, "agent") == Some("executor-pi")
            })
            .unwrap();
        let log = fs::read_to_string(payload_string(wake, "logPath").unwrap()).unwrap();
        assert!(
            log.contains("coordination/runtime/review-inbox/r53/B903-A0001-nongate-executor-pi.md")
        );
        assert!(!log.contains("coordination/runtime/nongate-inbox/"));

        let recorded = ledger::event(
            "TaskRecorded",
            "runtime:orch",
            Some("B903"),
            Some("r53"),
            serde_json::json!({"attemptId": "B903-A0001"}),
        );
        let mut retirement_batch = vec![recorded.clone()];
        retirement_batch.extend(crate::sites::retire_task_sites(
            &after_wake.events,
            "B903",
            &recorded.event_id,
        ));
        assert_eq!(
            retirement_batch
                .iter()
                .filter(|event| event.kind == crate::sites::SITE_RETIRED_EVENT_KIND)
                .count(),
            1
        );
        ledger::append(&root, "r53", &retirement_batch).unwrap();

        let outcome = crate::sites::reap_released_sites(&root, "r53").unwrap();
        assert_eq!(outcome.removed, vec![site_id]);
        assert!(outcome.refused.is_empty());
        assert!(outcome.target_failures.is_empty());
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn pi_stream_projection_preserves_launch_and_proves_completed_tool_output() {
        let root = temp_root("pi-stream-projection");
        let fake_bin = root.join("bin");
        fs::create_dir_all(&fake_bin).unwrap();
        let capture = root.join("argv.json");
        let fake_pi = fake_bin.join("pi");
        fs::write(
            &fake_pi,
            r#"#!/bin/sh
python3 - "$@" <<'PY'
import json, os, sys
with open(os.environ["PI_ARGS_CAPTURE"], "w", encoding="utf-8") as stream:
    json.dump(sys.argv[1:], stream)
print('{"type":"session","id":"pi-test-session"}')
print('{"type":"turn_start"}')
print('{"type":"message_start","message":{"role":"user","content":[{"type":"text","text":"PROMPT_SECRET"}]}}')
print('{"type":"tool_execution_start","toolCallId":"tool-1","toolName":"bash","args":{"command":"PROMPT_SECRET"}}')
print('{"type":"tool_execution_end","toolCallId":"tool-1","toolName":"bash","result":{"content":[{"type":"text","text":"ORCH_PI_PROBE_TEST"}],"details":{}},"isError":false}')
print('{"type":"message_end","message":{"role":"assistant","content":[{"type":"text","text":"ASSISTANT_SECRET"}]}}')
print('{"type":"agent_settled"}')
PY
"#,
        )
        .unwrap();
        fs::set_permissions(&fake_pi, fs::Permissions::from_mode(0o755)).unwrap();

        let inherited_path = std::env::var("PATH").unwrap_or_default();
        let output = Command::new("/bin/sh")
            .arg(Path::new(env!("CARGO_MANIFEST_DIR")).join("../../scripts/wake-pi-stream.sh"))
            .arg("PROMPT_SECRET")
            .env("ORCH_PI_CWD", &root)
            .env("ORCH_PI_TIMEOUT", "30")
            .env("ORCH_PI_PROVIDER", "deepseek")
            .env("ORCH_PI_MODEL", "deepseek-v4-pro")
            .env("ORCH_PI_EFFORT", "max")
            .env("PI_ARGS_CAPTURE", &capture)
            .env("PATH", format!("{}:{inherited_path}", fake_bin.display()))
            .output()
            .unwrap();
        assert!(
            output.status.success(),
            "projection failed: {}",
            String::from_utf8_lossy(&output.stderr)
        );

        let projected = String::from_utf8(output.stdout).unwrap();
        assert_eq!(
            probe_challenge_observed(&projected, "ORCH_PI_PROBE_TEST"),
            Some(ReviewProbeSource::ClawToolOutput)
        );
        assert!(projected.lines().any(|line| line == "turn.started"));
        assert!(projected.contains(r#"{"type":"agent_settled"}"#));
        assert!(!projected.contains("PROMPT_SECRET"));
        assert!(!projected.contains("ASSISTANT_SECRET"));
        assert!(projected.lines().all(|line| line.len() <= 64 * 1024));

        let argv: Vec<String> = serde_json::from_slice(&fs::read(&capture).unwrap()).unwrap();
        assert_eq!(
            argv,
            vec![
                "-p",
                "PROMPT_SECRET",
                "--mode",
                "json",
                "--provider",
                "deepseek",
                "--model",
                "deepseek-v4-pro",
                "--thinking",
                "max",
            ]
        );
        fs::remove_dir_all(root).unwrap();
    }

    const B225_PI_CHALLENGE: &str = "B225_PI_PROJECTED_SENTINEL";

    fn pi_stream_script_path() -> PathBuf {
        PathBuf::from(env!("CARGO_MANIFEST_DIR"))
            .join("../../..")
            .join(PI_STREAM_SCRIPT_REL)
    }

    fn pi_stream_stub(root: &Path) -> (PathBuf, std::ffi::OsString) {
        let bin = root.join("bin");
        fs::create_dir_all(&bin).unwrap();
        let pi = bin.join("pi");
        fs::write(
            &pi,
            r#"#!/usr/bin/python3
import json
import os
import sys
import time

def emit(value):
    print(json.dumps(value, separators=(",", ":")), flush=True)

emit({"type": "session", "id": "b225-pi-stub"})
emit({"type": "turn_start"})
emit({"type": "message_start", "message": {"role": "user", "content": "PROMPT_MUST_NOT_LEAK"}})
emit({
    "type": "tool_execution_end",
    "toolCallId": "read-1",
    "toolName": "read",
    "result": {"content": [{"type": "text", "text": os.environ["PI_STUB_OUTPUT"]}]},
    "isError": False,
})
time.sleep(float(os.environ.get("PI_STUB_SLEEP", "0")))
emit({"type": "agent_settled"})
sys.exit(int(os.environ.get("PI_STUB_EXIT", "0")))
"#,
        )
        .unwrap();
        fs::set_permissions(&pi, fs::Permissions::from_mode(0o755)).unwrap();
        let mut paths = vec![bin.clone()];
        paths.extend(std::env::split_paths(
            &std::env::var_os("PATH").unwrap_or_default(),
        ));
        (pi, std::env::join_paths(paths).unwrap())
    }

    #[test]
    fn pi_stream_projects_probe_before_exit_without_leaking_prompt() {
        let root = temp_root("b225-pi-streaming-projection");
        fs::create_dir_all(&root).unwrap();
        let (_stub, path) = pi_stream_stub(&root);
        let mut child = Command::new("/bin/sh")
            .arg(pi_stream_script_path())
            .arg("PROMPT_MUST_NOT_LEAK")
            .env("PATH", path)
            .env("ORCH_PI_CWD", &root)
            .env("ORCH_PI_TIMEOUT", "30")
            .env("ORCH_PI_PROVIDER", "deepseek")
            .env("ORCH_PI_MODEL", "deepseek-v4-pro")
            .env("ORCH_PI_EFFORT", "max")
            .env("PI_STUB_OUTPUT", B225_PI_CHALLENGE)
            .env("PI_STUB_SLEEP", "2")
            .stdout(Stdio::piped())
            .stderr(Stdio::null())
            .spawn()
            .unwrap();
        let stdout = child.stdout.take().unwrap();
        let mut reader = BufReader::new(stdout);
        let mut projected = String::new();
        reader.read_line(&mut projected).unwrap();
        assert_eq!(projected, "turn.started\n");
        reader.read_line(&mut projected).unwrap();
        assert_eq!(
            probe_challenge_observed(&projected, B225_PI_CHALLENGE),
            Some(ReviewProbeSource::ClawToolOutput)
        );
        assert!(
            child.try_wait().unwrap().is_none(),
            "projected sentinel must be observable while pi is still running"
        );
        reader.read_to_string(&mut projected).unwrap();
        let status = child.wait().unwrap();
        assert!(status.success());
        assert!(!projected.contains("PROMPT_MUST_NOT_LEAK"));
        fs::remove_dir_all(root).unwrap();
    }

