    fn install_plain_review_provider(root: &Path, basename: &str) {
        let provider = root.join(basename);
        fs::write(
            &provider,
            "#!/bin/sh\nprintf '%s\\n' \"$1\" | sed 's/__VERDICT__/PASS/g'\n",
        )
        .unwrap();
        fs::set_permissions(&provider, fs::Permissions::from_mode(0o755)).unwrap();
        fs::write(
            root.join("coordination/agents.yaml"),
            serde_json::to_vec_pretty(&serde_json::json!({
                "agents": {
                    "executor-claw": {
                        "injectable": true,
                        "sessionId": "fresh-session-per-wake",
                        "mode": "fresh",
                        "wake": {"argv": [provider.display().to_string(), "{message}"]}
                    }
                }
            }))
            .unwrap(),
        )
        .unwrap();
    }

