    #[test]
    fn sandbox_probe_failure_is_durable_and_keeps_the_sent_record_and_site() {
        let root = review_wake_root("review-probe-failure");
        fs::write(
            root.join("probe-adapter.sh"),
            r#"#!/bin/sh
printf '%s\n' '{"type":"text","text":"probe deliberately skipped"}'
"#,
        )
        .unwrap();
        let plan = review_site_plan_generation(
            root.to_str().unwrap(),
            "B900-A0001",
            crate::sites::SiteRole::Primary,
            "executor-claw",
            1,
        )
        .unwrap();

        let refusal = run_wake_with_message_authorized_review(
            &root,
            "executor-claw",
            test_review_message(),
            test_review_request(),
        )
        .unwrap_err();
        let refusal = format!("{refusal:#}");
        assert!(refusal.contains("未消费"), "{refusal}");
        assert!(refusal.contains("忙碌会话吞掉"), "{refusal}");
        let ledger =
            orch_core::read_ledger(&root.join("coordination/rounds/r53/events.jsonl")).unwrap();
        assert!(ledger.events.iter().any(|event| event.kind == "WakeIssued"));
        assert!(ledger
            .events
            .iter()
            .any(|event| event.kind == "ReviewRequested"));
        let escalation = ledger
            .events
            .iter()
            .find(|event| {
                event.kind == "EscalationRaised"
                    && event
                        .payload
                        .as_ref()
                        .and_then(|payload| payload.get("stage"))
                        .and_then(serde_json::Value::as_str)
                        == Some("review-consumption")
            })
            .expect("failed review probe must leave a durable escalation");
        assert_eq!(escalation.task_id.as_deref(), Some("B900"));
        let payload = escalation.payload.as_ref().unwrap();
        assert_eq!(
            payload.get("taskId").and_then(serde_json::Value::as_str),
            Some("B900")
        );
        assert_eq!(
            payload.get("role").and_then(serde_json::Value::as_str),
            Some("primary")
        );
        assert_eq!(
            payload.get("agent").and_then(serde_json::Value::as_str),
            Some("executor-claw")
        );
        assert_eq!(
            payload.get("worktree").and_then(serde_json::Value::as_str),
            Some(plan.worktree.as_str())
        );
        assert_eq!(
            payload.get("targetDir").and_then(serde_json::Value::as_str),
            Some(plan.target_dir.as_str())
        );
        assert!(payload
            .get("wakeId")
            .and_then(serde_json::Value::as_str)
            .is_some());
        assert!(payload
            .get("logPath")
            .and_then(serde_json::Value::as_str)
            .is_some());

        let sentinels = fs::read_dir(&plan.target_dir)
            .unwrap()
            .filter_map(std::result::Result::ok)
            .filter(|entry| {
                entry
                    .file_name()
                    .to_string_lossy()
                    .starts_with(".orch-review-probe-")
            })
            .collect::<Vec<_>>();
        assert_eq!(
            sentinels.len(),
            1,
            "timed-out probe must retain its sentinel"
        );
        assert!(!fs::read_to_string(sentinels[0].path())
            .unwrap()
            .trim()
            .is_empty());
        fs::remove_dir_all(root).unwrap();
    }

