    #[test]
    fn delivered_main_repo_reviews_release_capacity_before_real_admission() {
        let root = review_wake_root_with_capacity("review-reconcile-real-entry", 3);
        fs::create_dir_all(root.join("coordination/rounds/r53/reviews")).unwrap();

        let mut events = Vec::new();
        for task in ["B900", "B901", "B902"] {
            let request = ReviewRequest {
                task_id: task.to_string(),
                attempt_id: format!("{task}-A0001"),
                role: "primary".to_string(),
                agent: "executor-claw".to_string(),
                deadline_secs: 900,
            };
            let mut event = review_request_event(&request).unwrap().into_record();
            event.round = Some("r53".to_string());
            events.push(event);
        }
        crate::ledger::append(&root, "r53", &events).unwrap();

        for task in ["B900", "B901"] {
            let reviewed_head =
                crate::gitx::rev_parse(&root, &format!("refs/heads/task/{task}")).unwrap();
            fs::write(
                root.join(format!(
                    "coordination/rounds/r53/reviews/{task}-A0001-primary-executor-claw.md"
                )),
                format!(
                    "---\ntaskId: {task}\nround: r53\nattemptId: {task}-A0001\nrole: primary\nreviewer: executor-claw\nverdict: PASS\nreviewedHead: {reviewed_head}\n---\nsubstantive review\n"
                ),
            )
            .unwrap();
        }
        review_test_git(
            &root,
            &[
                "add",
                "coordination/rounds/r53/events.jsonl",
                "coordination/rounds/r53/reviews/B900-A0001-primary-executor-claw.md",
                "coordination/rounds/r53/reviews/B901-A0001-primary-executor-claw.md",
            ],
        );
        review_test_git(
            &root,
            &[
                "-c",
                "user.name=orch-test",
                "-c",
                "user.email=orch-test@example.invalid",
                "commit",
                "-qm",
                "commit review deliveries",
            ],
        );

        let request = ReviewRequest {
            task_id: "B903".to_string(),
            attempt_id: "B903-A0001".to_string(),
            role: "primary".to_string(),
            agent: "executor-claw".to_string(),
            deadline_secs: 900,
        };
        run_wake_with_message_authorized_review(
            &root,
            "executor-claw",
            test_review_message(),
            request,
        )
        .unwrap();

        let ledger_path = root.join("coordination/rounds/r53/events.jsonl");
        let ledger = orch_core::read_ledger(&ledger_path).unwrap();
        let delivered = ledger
            .events
            .iter()
            .filter(|event| event.kind == "ReviewDelivered")
            .collect::<Vec<_>>();
        assert_eq!(delivered.len(), 2);
        assert!(delivered.iter().all(|event| {
            event.actor == "runtime:orch"
                && event.payload.as_ref().is_some_and(|payload| {
                    ["attemptId", "role", "agent", "bodyLen"]
                        .iter()
                        .all(|key| payload.get(key).is_some())
                })
        }));
        reconcile_review_delivery_slots(&root, "r53").unwrap();
        let ledger = orch_core::read_ledger(&ledger_path).unwrap();
        assert_eq!(
            ledger
                .events
                .iter()
                .filter(|event| event.kind == "ReviewDelivered")
                .count(),
            2,
            "reconciliation must be idempotent"
        );
        fs::remove_dir_all(root).unwrap();
    }

