    #[test]
    fn wake_engaged_after_ignores_stale_marks_before_offset() {
        // B100 负向变异 6 的自建回归：append 改造后，上一轮注入留下的
        // turn.started 不得把本轮空注入（尚未产出任何字节）误判成已咬合。
        let mut log = String::from(
            "ERROR failed to load skill /x/SKILL.md\n{\"type\":\"turn.started\",\"ts\":\"prev-round\"}\n",
        );
        // 本次注入写入前记录的文件长度当 offset
        let offset = log.len();
        // 本轮注入失败/尚未产出 → offset 之后无新内容 → 未咬合
        assert!(
            !wake_engaged_after(&log, offset),
            "上一轮遗留的 turn.started 不得判定本轮咬合"
        );
        // 对照：旧的整份日志判读会误判（这正是 B100 必修的回归点）
        assert!(
            wake_engaged(&log),
            "整份日志含历史 turn.started（旧语义会把本轮空注入误判成已咬合）"
        );
        // 本轮真正产出咬合标记（写在 offset 之后）→ 咬合
        log.push_str("{\"type\":\"thread.started\"}\n");
        assert!(
            wake_engaged_after(&log, offset),
            "offset 之后的新咬合标记应判咬合"
        );
        // offset 越界 ⇒ 无新内容 ⇒ 未咬合（保守方向）
        assert!(!wake_engaged_after(&log, log.len() + 1));
    }

    /// B100 修复轮 D1 回归：remove 失败（权限/占用）时，旧 legacy 必须被截断
    /// 为空——上一轮的 turn.started 绝不允许留在本次注入的整份判读视野里，
    /// 且失败原因必须写进本次 per-attempt 日志。
    #[test]
    fn relink_remove_failure_purges_stale_engagement_marks() {
        let root = temp_root("relink-remove-fail");
        fs::create_dir_all(&root).unwrap();
        let legacy = root.join("wake-worker.log");
        let attempt = root.join("wake-worker-attempt.jsonl");
        fs::write(
            &legacy,
            "{\"type\":\"turn.started\",\"ts\":\"prev-round\"}\n",
        )
        .unwrap();
        fs::write(&attempt, "").unwrap();

        let notes = std::cell::RefCell::new(Vec::<String>::new());
        let outcome = relink_legacy_wake_log_with(
            "worker",
            &legacy,
            &attempt,
            |_p| Err(io::Error::new(io::ErrorKind::PermissionDenied, "locked")),
            |_src, _dst| panic!("remove 失败后不得再尝试 hard_link"),
            |_p, line| {
                notes.borrow_mut().push(line.to_string());
                Ok(())
            },
        )
        .unwrap();

        assert_eq!(outcome, LegacyProbeState::DegradedEmpty);
        let content = fs::read_to_string(&legacy).unwrap();
        assert!(
            !content.contains("thread.started") && !content.contains("turn.started"),
            "轮换失败后 legacy 不得残留任何历史咬合标记，实际内容: {content:?}"
        );
        assert!(
            content.is_empty(),
            "fail-closed 要求截断为空，实际: {content:?}"
        );
        assert_eq!(
            notes.borrow().len(),
            1,
            "失败原因必须写进本次 per-attempt 日志"
        );
        assert!(notes.borrow()[0].contains("remove"));
        fs::remove_dir_all(root).unwrap();
    }

    /// B100 修复轮 D1 极端角：remove 与截断都失败 ⇒ 无法保证 legacy 不含历史
    /// 标记 ⇒ 必须中止注入（Err），绝不在可能残留旧标记的状态下继续 spawn。
    /// （前置：非 root 运行——0o444 只读文件使 File::create 截断失败。）
    #[test]
    #[cfg(unix)]
    fn relink_unenforceable_failure_aborts_injection() {
        use std::os::unix::fs::PermissionsExt;
        let root = temp_root("relink-abort");
        fs::create_dir_all(&root).unwrap();
        let legacy = root.join("wake-worker.log");
        let attempt = root.join("wake-worker-attempt.jsonl");
        fs::write(
            &legacy,
            "{\"type\":\"turn.started\",\"ts\":\"prev-round\"}\n",
        )
        .unwrap();
        fs::write(&attempt, "").unwrap();
        fs::set_permissions(&legacy, fs::Permissions::from_mode(0o444)).unwrap();

        let notes = std::cell::RefCell::new(Vec::<String>::new());
        let result = relink_legacy_wake_log_with(
            "worker",
            &legacy,
            &attempt,
            |_p| Err(io::Error::new(io::ErrorKind::PermissionDenied, "busy")),
            |_src, _dst| panic!("不应到达 hard_link"),
            |_p, line| {
                notes.borrow_mut().push(line.to_string());
                Ok(())
            },
        );

        assert!(
            result.is_err(),
            "remove+truncate 双失败必须中止注入（fail-closed）"
        );
        let err = result.unwrap_err().to_string();
        assert!(
            err.contains("fail-closed"),
            "错误文案需说明 fail-closed 语义: {err}"
        );
        assert_eq!(
            notes.borrow().len(),
            2,
            "两次失败原因都要写进 per-attempt 日志"
        );
        fs::set_permissions(&legacy, fs::Permissions::from_mode(0o644)).unwrap();
        fs::remove_dir_all(root).unwrap();
    }

    /// B100 修复轮 D2 回归：hard_link 失败时不退化 copy（copy 复制的是 relink
    /// 那一刻的空文件且永不更新 = 必假阴性中间态）；legacy 必须保持缺席
    /// （读到 ENOENT ≡ 空，保守方向），判读走 per-attempt 路径。
    #[test]
    fn relink_hard_link_failure_leaves_legacy_absent_without_copy() {
        let root = temp_root("relink-link-fail");
        fs::create_dir_all(&root).unwrap();
        let legacy = root.join("wake-worker.log");
        let attempt = root.join("wake-worker-attempt.jsonl");
        fs::write(
            &legacy,
            "{\"type\":\"thread.started\",\"ts\":\"prev-round\"}\n",
        )
        .unwrap();
        fs::write(&attempt, "").unwrap();

        let notes = std::cell::RefCell::new(Vec::<String>::new());
        let outcome = relink_legacy_wake_log_with(
            "worker",
            &legacy,
            &attempt,
            |p| fs::remove_file(p),
            |_src, _dst| Err(io::Error::new(io::ErrorKind::Other, "cross-device link")),
            |_p, line| {
                notes.borrow_mut().push(line.to_string());
                Ok(())
            },
        )
        .unwrap();

        assert_eq!(outcome, LegacyProbeState::DegradedAbsent);
        assert!(
            !legacy.exists(),
            "hard_link 失败后 legacy 必须保持缺席（绝不留下 copy 退化出来的陈旧副本）"
        );
        assert_eq!(notes.borrow().len(), 1);
        assert!(notes.borrow()[0].contains("hard-link"));
        fs::remove_dir_all(root).unwrap();
    }

    /// 成功路径对照：remove + hard_link 走真实 fs——旧 legacy 的历史字节不再
    /// 可达，legacy 与 per-attempt 共享 inode（relink 后写进 attempt 的内容
    /// 经 legacy 名字可见），全程无降级日志。
    #[test]
    fn relink_success_shares_attempt_inode() {
        let root = temp_root("relink-ok");
        fs::create_dir_all(&root).unwrap();
        let legacy = root.join("wake-worker.log");
        let attempt = root.join("wake-worker-attempt.jsonl");
        fs::write(
            &legacy,
            "{\"type\":\"turn.started\",\"ts\":\"prev-round\"}\n",
        )
        .unwrap();
        fs::write(&attempt, "").unwrap();

        let notes = std::cell::RefCell::new(Vec::<String>::new());
        let outcome = relink_legacy_wake_log_with(
            "worker",
            &legacy,
            &attempt,
            |p| fs::remove_file(p),
            |src, dst| fs::hard_link(src, dst),
            |_p, line| {
                notes.borrow_mut().push(line.to_string());
                Ok(())
            },
        )
        .unwrap();

        assert_eq!(outcome, LegacyProbeState::Linked);
        assert!(notes.borrow().is_empty(), "成功路径不得写降级日志");
        let mut f = fs::OpenOptions::new().append(true).open(&attempt).unwrap();
        writeln!(f, "{{\"type\":\"turn.started\",\"ts\":\"this-round\"}}").unwrap();
        drop(f);
        let via_legacy = fs::read_to_string(&legacy).unwrap();
        assert!(
            via_legacy.contains("this-round"),
            "inode 共享：attempt 的新内容必须经 legacy 可见"
        );
        assert!(
            !via_legacy.contains("prev-round"),
            "旧 legacy 的历史字节不得再可达"
        );
        fs::remove_dir_all(root).unwrap();
    }

    fn overlay_event(
        event_id: &str,
        kind: &str,
        payload: serde_json::Value,
    ) -> orch_core::EventRecord {
        orch_core::EventRecord {
            event_id: event_id.to_string(),
            ts: "2026-07-26T00:00:00Z".to_string(),
            actor: "test".to_string(),
            kind: kind.to_string(),
            task_id: None,
            round: Some("r1".to_string()),
            payload: Some(payload),
            extra: Default::default(),
        }
    }

    fn write_overlay_ledger(root: &Path, events: &[orch_core::EventRecord]) {
        let dir = root.join("coordination/rounds/r1");
        fs::create_dir_all(&dir).unwrap();
        let text = events
            .iter()
            .map(|event| serde_json::to_string(event).unwrap())
            .collect::<Vec<_>>()
            .join("\n");
        fs::write(dir.join("events.jsonl"), format!("{text}\n")).unwrap();
    }

    fn delivered_event(log_path: &Path, generation: &str) -> orch_core::EventRecord {
        overlay_event(
            &format!("delivered-{generation}"),
            "DispatchWakeDelivered",
            serde_json::json!({
                "agent": "worker",
                "actionId": format!("action-{generation}"),
                "attemptId": "B114-A0002",
                "attemptNo": 2,
                "pid": 42,
                "logPath": log_path.display().to_string(),
                "probeOffset": 0,
                "probeEnd": 0,
                "leaseGeneration": generation,
            }),
        )
    }

    fn applied_event(generation: &str) -> orch_core::EventRecord {
        overlay_event(
            "applied-1",
            "SessionOverlayApplied",
            serde_json::json!({
                "agent": "worker",
                "fault": "thread-not-found",
                "faultEventId": "delivered-old",
                "generation": generation,
            }),
        )
    }

    #[test]
    fn overlay_clears_only_on_new_generation_exact_engaged_evidence() {
        let root = temp_root("overlay-clear-engaged");
        fs::create_dir_all(&root).unwrap();
        let log = root.join("wake-worker.log");
        fs::write(&log, "{\"type\":\"turn.started\"}\n").unwrap();
        write_overlay_ledger(
            &root,
            &[
                applied_event("lease-old"),
                delivered_event(&log, "lease-new"),
            ],
        );

        let resolved =
            reconcile_session_overlay(&root, "r1", "worker", SessionMode::Resume).unwrap();
        assert_eq!(resolved.effective, SessionMode::Resume);
        let events = read_round_events(&root, "r1").unwrap();
        assert!(active_session_overlay(&events, "worker").is_none());
        let cleared = events
            .iter()
            .find(|event| event.kind == "SessionOverlayCleared")
            .expect("应落 durable Cleared");
        assert_eq!(payload_string(cleared, "generation"), Some("lease-new"));
        assert_eq!(payload_string(cleared, "appliedEventId"), Some("applied-1"));
        let evidence = cleared
            .payload
            .as_ref()
            .and_then(|payload| payload.get("engagedEvidence"))
            .unwrap();
        assert_eq!(
            evidence.get("engaged").and_then(|v| v.as_bool()),
            Some(true)
        );
        assert!(evidence.get("probeEnd").and_then(|v| v.as_u64()).unwrap() > 0);
        fs::remove_dir_all(root).unwrap();
    }

    #[test]
    fn delivered_empty_window_same_generation_and_exit_do_not_clear_overlay() {
        for (name, log_text, generation) in [
            ("empty", "", "lease-new"),
            (
                "same-generation",
                "{\"type\":\"thread.started\"}\n",
                "lease-old",
            ),
        ] {
            let root = temp_root(&format!("overlay-no-clear-{name}"));
            fs::create_dir_all(&root).unwrap();
            let log = root.join("wake-worker.log");
            fs::write(&log, log_text).unwrap();
            write_overlay_ledger(
                &root,
                &[
                    applied_event("lease-old"),
                    delivered_event(&log, generation),
                ],
            );
            let resolved =
                reconcile_session_overlay(&root, "r1", "worker", SessionMode::Resume).unwrap();
            assert_eq!(resolved.effective, SessionMode::Fresh, "case={name}");
            let events = read_round_events(&root, "r1").unwrap();
            assert!(active_session_overlay(&events, "worker").is_some());
            assert!(!events
                .iter()
                .any(|event| event.kind == "SessionOverlayCleared"));
            // 无 pid/liveness 条件参与重放：进程退出/重启不会清 durable overlay。
            let replayed =
                active_session_overlay(&read_round_events(&root, "r1").unwrap(), "worker");
            assert!(replayed.is_some());
            fs::remove_dir_all(root).unwrap();
        }
    }

