    #[test]
    fn b191_ten_nonterminal_children_hit_the_monotonic_deadline_and_reap() {
        for iteration in 0..10 {
            let root = temp_root(&format!("b191-deadline-{iteration}"));
            fs::create_dir_all(&root).unwrap();
            let log_path = root.join("wake.jsonl");
            let stdout = File::create(&log_path).unwrap();
            let stderr = stdout.try_clone().unwrap();
            // Spawn the provider image directly: the contract here is the
            // absolute runtime boundary, not the shell's exec transition.
            // The latter is covered separately by the B177 credential-refresh
            // fixtures and must remain fail-closed at the signal boundary.
            let child = Command::new("/bin/sleep")
                .arg("5")
                .stdin(Stdio::null())
                .stdout(Stdio::from(stdout))
                .stderr(Stdio::from(stderr))
                .process_group(0)
                .spawn()
                .unwrap();
            let started = Instant::now();
            let outcome = supervise_managed_child_with_runtime_limit(
                child,
                "opencode",
                &log_path,
                WakeSupervisorPolicy {
                    natural_exit_grace_ms: 20,
                    term_grace_ms: 20,
                    poll_interval_ms: 5,
                },
                managed_wake_runtime_limit(Some(1)),
            )
            .unwrap();
            assert!(started.elapsed() >= Duration::from_millis(900));
            assert!(started.elapsed() < Duration::from_secs(4));
            assert_eq!(
                outcome.completion_reason,
                ManagedWakeStopReason::HardDeadline
            );
            assert!(outcome.hard_deadline_reached);
            assert!(outcome.process_tree_terminated);
            fs::remove_dir_all(root).unwrap();
        }
    }

    #[test]
    fn b191_concurrent_cancel_is_first_writer_wins_and_status_is_separate() {
        let root = temp_root("b191-concurrent-cancel");
        fs::create_dir_all(root.join("coordination/runtime")).unwrap();
        let dir = authenticated_supervisor_dir(&root, true).unwrap();
        let wake_id = "019fc001-1111-4222-8333-444455556666";
        let token = "0123456789abcdef0123456789abcdef";
        let status_path = dir.join(format!("{token}.status.json"));
        let mut control = ManagedWakeControlRuntime::publish(
            &root,
            wake_id,
            token,
            std::process::id(),
            std::process::id(),
            &status_path,
            managed_wake_runtime_limit(Some(1_800)),
            Instant::now(),
            None,
        )
        .unwrap();
        let supervisor = std::thread::spawn(move || {
            let deadline = Instant::now() + Duration::from_secs(5);
            while Instant::now() < deadline {
                if control.poll_authenticated_cancel(None).unwrap() {
                    return control;
                }
                std::thread::sleep(Duration::from_millis(2));
            }
            panic!("cancel request was never observed");
        });
        let barrier = std::sync::Arc::new(std::sync::Barrier::new(20));
        let mut callers = Vec::new();
        for index in 0..20 {
            let root = root.clone();
            let barrier = barrier.clone();
            callers.push(std::thread::spawn(move || {
                barrier.wait();
                request_managed_wake_cancel(&root, wake_id, &format!("reason-{index}")).unwrap()
            }));
        }
        let results = callers
            .into_iter()
            .map(|caller| caller.join().unwrap())
            .collect::<Vec<_>>();
        assert_eq!(
            results
                .iter()
                .filter(|result| { result.disposition == ManagedWakeCancelDisposition::Accepted })
                .count(),
            1
        );
        assert!(results.iter().all(|result| matches!(
            result.disposition,
            ManagedWakeCancelDisposition::Accepted | ManagedWakeCancelDisposition::AlreadyCanceling
        )));
        assert!(results
            .iter()
            .all(|result| result.request_id == results[0].request_id));
        assert!(results
            .iter()
            .all(|result| result.reason == results[0].reason));

        let control = supervisor.join().unwrap();
        control
            .publish_stop(ManagedWakeStopReason::ManualCancel)
            .unwrap();
        let stop_bytes = fs::read(&control.stop_path).unwrap();
        let stop_value: serde_json::Value = serde_json::from_slice(&stop_bytes).unwrap();
        assert_eq!(stop_value["completionReason"], "manual-cancel");
        assert!(stop_value.get("managedScopeTerminated").is_none());
        assert!(control
            .publish_stop(ManagedWakeStopReason::HardDeadline)
            .is_err());
        assert_eq!(fs::read(&control.stop_path).unwrap(), stop_bytes);

        let containment = production_managed_containment(true);
        let status = WakeSupervisorStatus {
            protocol_revision: WAKE_SUPERVISOR_PROTOCOL_REVISION,
            token: token.to_string(),
            wake_id: wake_id.to_string(),
            agent: Some("executor-opencode".to_string()),
            runtime_limit: managed_wake_runtime_limit(Some(1_800)),
            completion_reason: ManagedWakeStopReason::ManualCancel,
            hard_deadline_reached: false,
            cancel_request_id: Some(results[0].request_id.clone()),
            cancel_reason: Some(results[0].reason.clone()),
            terminal_seen: false,
            exited_naturally: false,
            signals: vec!["TERM".to_string()],
            containment_capability: containment.capability,
            containment_claim: containment.claim,
            managed_scope_terminated: true,
            fork_complete: false,
            process_tree_terminated: false,
            owned_helpers: 1,
            termination_order: vec![41, 42],
            ambiguity: Vec::new(),
            exit_status: Some(0),
            error: None,
            topology_snapshots: 2,
            full_credential_inspections: 2,
            log_bytes_read: 0,
            last_frame_age_secs: None,
            last_frame_summary: None,
            elapsed_secs: Some(1),
        };
        atomic_create_json(&status_path, &status).unwrap();
        let repeated =
            request_managed_wake_cancel(&root, wake_id, "different-late-reason").unwrap();
        assert_eq!(
            repeated.disposition,
            ManagedWakeCancelDisposition::AlreadyTerminal
        );
        assert!(repeated.managed_scope_terminated);
        assert_eq!(repeated.request_id, results[0].request_id);
        assert_eq!(repeated.reason, results[0].reason);
        fs::remove_dir_all(root).unwrap();
    }

    fn wait_for_stubborn_provider_terminal(log_path: &Path, deadline: Instant) -> Result<()> {
        loop {
            let log = fs::read(log_path).with_context(|| {
                format!(
                    "read stubborn-provider wake log while awaiting readiness: {}",
                    log_path.display()
                )
            })?;
            if log
                .split(|byte| *byte == b'\n')
                .any(|line| line == B177_FIXTURE_TERMINAL_RECORD)
            {
                return Ok(());
            }
            if Instant::now() >= deadline {
                bail!(
                    "stubborn provider did not emit its post-handler terminal record before deadline: {}",
                    log_path.display()
                );
            }
            std::thread::sleep(Duration::from_millis(5));
        }
    }

    #[test]
    fn b191_real_managed_supervisor_cancel_uses_the_existing_cleanup_owner() {
        let root = temp_root("b191-real-supervisor-cancel");
        let logs = root.join("coordination/runtime/logs");
        let bin = root.join("bin");
        fs::create_dir_all(&logs).unwrap();
        fs::create_dir_all(&bin).unwrap();
        let program = bin.join("opencode");
        fs::copy(std::env::current_exe().unwrap(), &program).unwrap();
        fs::set_permissions(&program, fs::Permissions::from_mode(0o755)).unwrap();
        let log_path = logs.join("wake-opencode.jsonl");
        File::create(&log_path).unwrap();
        let argv = vec![
            program.to_string_lossy().into_owned(),
            "--exact".to_string(),
            B177_STUBBORN_PROVIDER_TEST.to_string(),
            "--nocapture".to_string(),
            "--test-threads=1".to_string(),
        ];
        let wake_id = fresh_managed_wake_id();
        let provider_pid = spawn_managed_wake_supervisor(
            &root,
            "executor-opencode",
            &argv,
            &log_path,
            &wake_id,
            managed_wake_runtime_limit(None),
            &BTreeMap::new(),
            None,
        )
        .unwrap();
        assert!(provider_pid > 0);
        let deadline = Instant::now() + Duration::from_secs(15);
        wait_for_stubborn_provider_terminal(&log_path, deadline).unwrap();
        let cancel = request_managed_wake_cancel(&root, &wake_id, "bounded test cancel").unwrap();
        assert!(matches!(
            cancel.disposition,
            ManagedWakeCancelDisposition::Accepted | ManagedWakeCancelDisposition::AlreadyCanceling
        ));
        assert_eq!(
            cancel.completion_reason,
            Some(ManagedWakeStopReason::ManualCancel)
        );

        let (dir, descriptor) = read_managed_wake_control_descriptor(&root, &wake_id).unwrap();
        while !descriptor.status_path.exists() && Instant::now() < deadline {
            std::thread::sleep(Duration::from_millis(10));
        }
        let status_body = secure_read_lf_frame(
            &descriptor.status_path,
            &dir,
            MAX_MANAGED_WAKE_CONTROL_BYTES,
        )
        .unwrap();
        let status: WakeSupervisorStatus = serde_json::from_slice(&status_body).unwrap();
        assert_eq!(
            status.completion_reason,
            ManagedWakeStopReason::ManualCancel
        );
        assert!(!status.hard_deadline_reached);
        assert_eq!(status.cancel_request_id, Some(cancel.request_id));
        assert_eq!(status.cancel_reason.as_deref(), Some("bounded test cancel"));
        assert_eq!(status.signals, vec!["TERM", "KILL"]);
        assert!(status.managed_scope_terminated);
        assert_eq!(status.termination_order.last(), Some(&provider_pid));
        assert!(status.error.is_none());
        let stop =
            secure_read_lf_frame(&descriptor.stop_path, &dir, MAX_MANAGED_WAKE_CONTROL_BYTES)
                .unwrap();
        let stop_value: serde_json::Value = serde_json::from_slice(&stop).unwrap();
        assert_eq!(stop_value["completionReason"], "manual-cancel");
        assert!(stop_value.get("managedScopeTerminated").is_none());
        wait_for_managed_supervisor_reaped(&dir, &descriptor, deadline);
        fs::remove_dir_all(root).unwrap();
    }

